import React, { createContext, useState, useContext, useEffect, useCallback, useRef } from 'react';
import { getUserAccessLevel, getAccessLevelDisplay, ACCESS_LEVELS } from '../../utils/accessControl';
import { backendGet, backendPost } from '../../utils/backendApi';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [processedCodes, setProcessedCodes] = useState(new Set());
  const [accessLevel, setAccessLevel] = useState(ACCESS_LEVELS.PUBLIC);

  // Comprehensive credential management cleanup
  const clearAllCredentials = useCallback(async () => {
    try {
      // 1. Clear Google Identity Services state
      if (window.google && window.google.accounts && window.google.accounts.id) {
        window.google.accounts.id.disableAutoSelect();
        // Also cancel any pending prompts
        window.google.accounts.id.cancel();
      }

      // 2. Clear browser credential management if available
      if (navigator.credentials && navigator.credentials.preventSilentAccess) {
        await navigator.credentials.preventSilentAccess();
      }

      // 3. Clear any stored FedCM state
      if (window.PasswordCredential) {
        try {
          // Force clear any stored password credentials
          await navigator.credentials.store();
        } catch (e) {
          // Silent fail if not supported
        }
      }

      // 4. Clear session storage items that might affect FedCM
      try {
        sessionStorage.removeItem('google_signin_state');
        sessionStorage.removeItem('fedcm_auto_select_disabled');
        sessionStorage.removeItem('github_auth_state');
      } catch (e) {
        // Silent fail if sessionStorage is not available
      }

      console.log('🧹 All credential states cleared');
    } catch (error) {
      console.warn('⚠️ Error clearing credential states:', error);
    }
  }, []);

  // Enhanced login handler with provider switching support
  const login = useCallback(async (userData, provider) => {
    // Clear any previous authentication state from other providers
    if (user && user.provider !== provider) {
      console.log(`🔄 Switching from ${user.provider} to ${provider}, clearing credentials...`);
      await clearAllCredentials();
    }

    const userInfo = {
      ...userData,
      provider,
      loginTime: new Date().toISOString()
    };
    
    // Determine access level
    const userAccessLevel = getUserAccessLevel(userInfo);
    
    setUser(userInfo);
    setIsAuthenticated(true);
    setAccessLevel(userAccessLevel);
    localStorage.setItem('user', JSON.stringify(userInfo));
    
    console.log(`✅ Successfully logged in with ${provider}, Access Level: ${userAccessLevel}`);
  }, [clearAllCredentials, user]);

  // Handle Google credential response
  const handleGoogleCredentialResponse = useCallback(async (response) => {
    try {
      const userInfo = await backendPost('/auth/google', { credential: response.credential });
      await login(userInfo, 'google');
    } catch (error) {
      console.error('Error processing Google credential:', error);
      alert('Google authentication failed. Please try again.');
    }
  }, [login]);

  // Enhanced Google initialization with cleanup - Use useRef to store the callback
  const handleGoogleCredentialResponseRef = useRef();
  handleGoogleCredentialResponseRef.current = handleGoogleCredentialResponse;

  const initializeGoogleSignIn = useCallback(async () => {
    const googleClientId = process.env.REACT_APP_GOOGLE_CLIENT_ID;
    if (googleClientId && window.google) {
      try {
        // Clear any previous state first
        await clearAllCredentials();
        
        // Initialize fresh - use ref to avoid dependency
        window.google.accounts.id.initialize({
          client_id: googleClientId,
          callback: (response) => handleGoogleCredentialResponseRef.current(response),
          auto_select: false, // Disable auto-select to prevent conflicts
          cancel_on_tap_outside: false, // Prevent accidental cancellations
        });
        
        console.log('✅ Google Sign-In initialized with cleanup');
      } catch (error) {
        console.error('❌ Error initializing Google Sign-In:', error);
      }
    }
  }, [clearAllCredentials]);

  // Load user from localStorage on component mount
  useEffect(() => {
    const restoreSession = async () => {
      try {
        const { user: userData } = await backendGet('/auth/session');
        if (!userData) throw new Error('No active session');
        const userAccessLevel = getUserAccessLevel(userData);
        setUser(userData);
        setIsAuthenticated(true);
        setAccessLevel(userAccessLevel);
        localStorage.setItem('user', JSON.stringify(userData));
        console.log(`🔄 Restored user session, Access Level: ${userAccessLevel}`);
      } catch (error) {
        localStorage.removeItem('user');
        setUser(null);
        setIsAuthenticated(false);
        setAccessLevel(ACCESS_LEVELS.PUBLIC);
      }
    };

    restoreSession();

    // Initialize Google Sign-In API with proper cleanup
    initializeGoogleSignIn();
  }, [initializeGoogleSignIn]);

  // Enhanced logout handler with comprehensive cleanup
  const logout = async () => {
    console.log('🔄 Starting logout process...');

    try {
      await backendPost('/auth/logout', {});
    } catch (error) {
      console.warn('Unable to clear the server session:', error);
    }
    
    // Clear all credential states
    await clearAllCredentials();
    
    // Clear local state
    setUser(null);
    setIsAuthenticated(false);
    setAccessLevel(ACCESS_LEVELS.PUBLIC);
    localStorage.removeItem('user');
    
    console.log('✅ Logout complete with credential cleanup');
  };

  // GitHub login handler with pre-cleanup
  const loginWithGitHub = async () => {
    const githubClientId = process.env.REACT_APP_GITHUB_CLIENT_ID;
    const redirectUri = process.env.REACT_APP_REDIRECT_URI;
    
    if (!githubClientId || !redirectUri) {
      console.error('GitHub OAuth configuration is missing. Please check your .env file.');
      return;
    }
    
    // Clear credentials before GitHub login to prevent conflicts
    await clearAllCredentials();
    const state = crypto.randomUUID();
    sessionStorage.setItem('github_oauth_state', state);

    // Use window.location.href instead of window.open to redirect in the same window
    const authorizeParams = new URLSearchParams({
      client_id: githubClientId,
      redirect_uri: redirectUri,
      scope: 'read:user',
      state
    });
    window.location.href = `https://github.com/login/oauth/authorize?${authorizeParams}`;
  };

  // Handle GitHub OAuth callback
  const handleGitHubCallback = async (code, state) => {
    // Prevent duplicate processing of the same code
    if (processedCodes.has(code)) {
      console.log('⚠️ Code already processed, skipping...');
      return;
    }
    
    // Mark this code as being processed
    setProcessedCodes(prev => new Set(prev).add(code));
    
    setIsLoading(true);
    try {
      const expectedState = sessionStorage.getItem('github_oauth_state');
      sessionStorage.removeItem('github_oauth_state');
      if (!state || !expectedState || state !== expectedState) {
        throw new Error('GitHub OAuth state validation failed');
      }

      const redirectUri = process.env.REACT_APP_REDIRECT_URI;
      const userInfo = await backendPost('/auth/github', { code, redirect_uri: redirectUri });
      await login(userInfo, 'github');

    } catch (error) {
      console.error('❌ Error during GitHub authentication:', error);
      
      alert('GitHub authentication failed. Please try again.');
      
      // Redirect to localhost:3000
      window.location.href = 'https://tomzhao.me';
      
    } finally {
      setIsLoading(false);
    }
  };

  // Enhanced Google login handler with cleanup
  const loginWithGoogle = async () => {
    if (!window.google || !window.google.accounts) {
      console.error('Google Identity Services not loaded');
      return;
    }

    try {
      // Only clear credentials if switching from another provider
      // Get current user state directly to avoid dependency issues
      const currentUser = localStorage.getItem('user');
      const parsedUser = currentUser ? JSON.parse(currentUser) : null;
      
      if (parsedUser && parsedUser.provider !== 'google') {
        console.log('🔄 Preparing for Google login, clearing previous auth state...');
        await clearAllCredentials();
        
        // Small delay to ensure cleanup is complete
        await new Promise(resolve => setTimeout(resolve, 300));
      }

      // Trigger the Google One Tap or popup sign-in
      window.google.accounts.id.prompt((notification) => {
        if (notification.isNotDisplayed() || notification.isSkippedMoment()) {
          console.log('🔄 Google prompt not displayed, trying alternative method...');
          
          // If prompt fails, try to create and render a temporary button
          const tempButtonId = 'temp-google-signin-' + Date.now();
          const tempDiv = document.createElement('div');
          tempDiv.id = tempButtonId;
          tempDiv.style.position = 'fixed';
          tempDiv.style.top = '-1000px';
          tempDiv.style.left = '-1000px';
          document.body.appendChild(tempDiv);
          
          try {
            window.google.accounts.id.renderButton(tempDiv, {
              theme: 'outline',
              size: 'large',
              type: 'standard',
              text: 'signin_with',
            });
            
            // Auto-click the button
            setTimeout(() => {
              const button = tempDiv.querySelector('div[role="button"]');
              if (button) {
                button.click();
              }
              // Clean up
              setTimeout(() => {
                if (tempDiv.parentNode) {
                  tempDiv.parentNode.removeChild(tempDiv);
                }
              }, 1000);
            }, 100);
          } catch (e) {
            console.error('❌ Error with alternative Google login:', e);
            if (tempDiv.parentNode) {
              tempDiv.parentNode.removeChild(tempDiv);
            }
          }
        }
      });
    } catch (error) {
      console.error('❌ Error during Google login preparation:', error);
    }
  };

  // Alternative method to render Google sign-in button
  const renderGoogleSignInButton = (elementId) => {
    if (window.google && window.google.accounts) {
      window.google.accounts.id.renderButton(
        document.getElementById(elementId),
        {
          theme: 'outline',
          size: 'large',
          type: 'standard',
          text: 'signin_with',
          logo_alignment: 'left'
        }
      );
    }
  };

  // Enhanced sign out function with comprehensive cleanup
  const signOut = async () => {
    console.log('🔄 Starting comprehensive sign out...');
    
    const currentProvider = user?.provider;
    
    // Provider-specific cleanup
    if (currentProvider === 'google') {
      try {
        if (window.google && window.google.accounts && window.google.accounts.id) {
          window.google.accounts.id.disableAutoSelect();
          window.google.accounts.id.cancel();
          console.log('🧹 Google-specific cleanup completed');
        }
      } catch (error) {
        console.error('⚠️ Error during Google sign out:', error);
      }
    } else if (currentProvider === 'github') {
      // For GitHub, clear any OAuth-related session data
      try {
        sessionStorage.removeItem('github_oauth_state');
        sessionStorage.removeItem('github_auth_code');
        console.log('🧹 GitHub-specific cleanup completed');
      } catch (error) {
        console.error('⚠️ Error during GitHub sign out:', error);
      }
    }
    
    // Comprehensive cleanup and logout
    await logout();
  };

  const value = {
    user,
    isAuthenticated,
    isLoading,
    accessLevel,
    login,
    logout,
    loginWithGitHub,
    loginWithGoogle,
    handleGitHubCallback,
    signOut,
    renderGoogleSignInButton,
    // Utility functions for access control
    getUserAccessLevel: () => getUserAccessLevel(user),
    getAccessLevelDisplay: (lang) => getAccessLevelDisplay(user, lang),
    isOwner: () => accessLevel === ACCESS_LEVELS.OWNER,
    isCloseFriend: () => accessLevel === ACCESS_LEVELS.FRIENDS || accessLevel === ACCESS_LEVELS.OWNER,
    hasAccess: (requiredLevel) => {
      switch (requiredLevel) {
        case ACCESS_LEVELS.PUBLIC:
          return true;
        case ACCESS_LEVELS.FRIENDS:
          return accessLevel === ACCESS_LEVELS.FRIENDS || accessLevel === ACCESS_LEVELS.OWNER;
        case ACCESS_LEVELS.OWNER:
          return accessLevel === ACCESS_LEVELS.OWNER;
        default:
          return false;
      }
    }
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext; 