import React, { useContext, useEffect } from 'react';
import '../../css/homepage.css';
import Preloader from '../Common/Preloader';
import Intro from './Intro';
import Activity from './Activity';
import PhotoGallery from './PhotoGallery';
import Board from './Board';
import Navigation from '../Common/Navigation';
import ChatBox from '../Common/ChatBox';
import WebsiteAnalytics from '../Common/WebsiteAnalytics';
import Analytics from '../Common/Analytics';
import Footer from '../Common/Footer';
import Blog from './Blog';
import { LanguageContext } from '../Common/LanguageProvider';
import { useAuth } from '../Common/AuthContext';

function Homepage() {
    const { lang } = useContext(LanguageContext);
    const { handleGitHubCallback, isLoading } = useAuth();

    // Handle GitHub OAuth callback
    useEffect(() => {
        const params = new URLSearchParams(window.location.search);
        const code = params.get("code");
        const state = params.get("state"); // Optional: for CSRF protection

        if (code) {
            console.log('GitHub OAuth code detected:', code);
            
            // Immediately clear the URL to prevent reuse
            const newUrl = window.location.origin + window.location.pathname;
            window.history.replaceState({}, document.title, newUrl);
            
            // Add a small delay to ensure URL is cleared before making the request
            setTimeout(() => {
                // Call the GitHub callback handler
                handleGitHubCallback(code, state)
                    .then(() => {
                        console.log('Authentication successful, URL already cleared');
                    })
                    .catch((error) => {
                        console.error('GitHub authentication failed:', error);
                    });
            }, 100);
        }
    }, [handleGitHubCallback]);

    return (
        <div className="myHomepage">
            <Preloader />
            <Navigation />
            
            {/* Show loading overlay during authentication */}
            {isLoading && (
                <div style={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    background: 'rgba(0, 0, 0, 0.7)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    zIndex: 9999,
                    color: 'white',
                    fontSize: '18px',
                    backdropFilter: 'blur(5px)'
                }}>
                    <div style={{ textAlign: 'center' }}>
                        <div style={{ marginBottom: '16px' }}>🔄</div>
                        <div>{{ en: "Authenticating...", zh: "正在验证..." }[lang]}</div>
                    </div>
                </div>
            )}
            
            <Intro />
            <Blog />
            {/* <AboutMe /> */}
            {/* <Skill /> */}
            <Activity />
            <PhotoGallery />
            <Board />
            {/* <Testimonial /> */}
            <ChatBox lang={lang} />
            <WebsiteAnalytics lang={lang} />
            <Analytics />
            <Footer />
        </div>
    );
}

export default Homepage;
