import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { LanguageContext } from '../Common/LanguageProvider';

// Base URL for the zhao-xuan.github.io repository config files
const CONFIG_REPO_BASE_URL = 'https://raw.githubusercontent.com/zhao-xuan/zhao-xuan.github.io/main/config';

// Function to fetch blog config from GitHub repository
const fetchBlogConfigFromRepo = async (language) => {
  try {
    console.log(`🔄 Fetching blog config for language: ${language}...`);
    
    const configUrl = `${CONFIG_REPO_BASE_URL}/${language}/blog.config.json`;
    
    const response = await axios.get(configUrl, {
      headers: {
        'Accept': 'application/json',
      },
      timeout: 10000, // 10 second timeout
    });

    if (response.status === 200 && response.data) {
      const config = response.data;
      console.log(`✅ Successfully fetched ${language} blog config`);
      console.log(`   - Last updated: ${config.lastUpdated}`);
      console.log(`   - Total streams: ${Object.keys(config.streams).length}`);
      return config;
    }
    
    return null;
    
  } catch (error) {
    console.error(`❌ Failed to fetch ${language} blog config:`, error.message);
    return null;
  }
};

// Fallback blog config for when remote config is unavailable
const getFallbackConfig = (language) => {
  const fallbackTitles = {
    en: { life: 'Life', study: 'Study', work: 'Work' },
    zh: { life: '生活', study: '学习', work: '工作' }
  };
  
  const fallbackDescriptions = {
    en: {
      life: 'Personal experiences and reflections',
      study: 'Learning and academic pursuits',
      work: 'Professional projects and insights'
    },
    zh: {
      life: '个人经历和思考',
      study: '学习和学术追求',
      work: '专业项目和见解'
    }
  };
  
  const titles = fallbackTitles[language] || fallbackTitles.en;
  const descriptions = fallbackDescriptions[language] || fallbackDescriptions.en;
  
  return {
    title: language === 'zh' ? '我的博客' : 'My Blog',
    lastUpdated: new Date().toISOString(),
    streams: {
      life: { title: titles.life, description: descriptions.life, articles: [] },
      study: { title: titles.study, description: descriptions.study, articles: [] },
      work: { title: titles.work, description: descriptions.work, articles: [] }
    }
  };
};

const BlogCard = ({ article }) => {
  const handleCardClick = () => {
    if (article.link && article.link !== '#') {
      window.open(article.link, '_blank');
    }
  };

  return (
    <div 
      className="blog-card" 
      onClick={handleCardClick} 
      style={{ 
        cursor: article.link && article.link !== '#' ? 'pointer' : 'default',
        backgroundImage: article.image ? `url(${article.image})` : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        height: '220px',
        borderRadius: '12px',
        position: 'relative',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-end',
        color: 'white',
        boxShadow: '0 4px 15px rgba(0, 0, 0, 0.2)',
        transition: 'transform 0.3s ease, box-shadow 0.3s ease'
      }}
      onMouseEnter={(e) => {
        if (article.link && article.link !== '#') {
          e.currentTarget.style.transform = 'translateY(-5px)';
          e.currentTarget.style.boxShadow = '0 8px 25px rgba(0, 0, 0, 0.3)';
        }
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = 'translateY(0)';
        e.currentTarget.style.boxShadow = '0 4px 15px rgba(0, 0, 0, 0.2)';
      }}
    >
      {/* Dark overlay for better text readability */}
      <div style={{
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: 'linear-gradient(to bottom, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.7) 100%)',
        zIndex: 1
      }} />
      
      {/* Content overlay */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        zIndex: 2,
        padding: '12px',
        background: 'rgba(0, 0, 0, 0.3)',
        backdropFilter: 'blur(10px)',
        borderRadius: '0 0 12px 12px'
      }}>
        <div className="blog-card-header" style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '8px',
          fontSize: '10px',
          opacity: 0.9
        }}>
          <span className="blog-date" style={{ color: 'rgba(255, 255, 255, 0.8)' }}>
            {article.date}
          </span>
          <span className="blog-author" style={{ color: 'rgba(255, 255, 255, 0.8)' }}>
            {article.author}
          </span>
        </div>
        
        <h3 className="blog-title" style={{
          margin: '0 0 6px 0',
          fontSize: '15px',
          fontWeight: '600',
          lineHeight: '1.2',
          color: 'white',
          textShadow: '0 2px 4px rgba(0, 0, 0, 0.5)'
        }}>
          {article.title}
        </h3>
        
        <p className="blog-description" style={{
          margin: 0,
          fontSize: '12px',
          lineHeight: '1.3',
          color: 'rgba(255, 255, 255, 0.9)',
          textShadow: '0 1px 2px rgba(0, 0, 0, 0.5)',
          display: '-webkit-box',
          WebkitLineClamp: 2,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden'
        }}>
          {article.description}
        </p>
      </div>
    </div>
  );
};

const BlogStream = ({ streamKey, stream, loading, lang }) => {
  if (loading) {
    return (
      <div className="blog-stream">
        <h2 className="stream-title">{streamKey}</h2>
        <div className="blog-loading" style={{ color: 'white' }}>
          {{ en: "Loading articles...", zh: "正在加载文章..." }[lang]}
        </div>
      </div>
    );
  }

  if (!stream) {
    return (
      <div className="blog-stream">
        <h2 className="stream-title">{streamKey}</h2>
        <div style={{
          textAlign: 'center',
          padding: '40px 20px',
          color: 'white',
          fontSize: '16px',
          fontWeight: '500',
          opacity: 0.8
        }}>
          {{ en: "Content is being updated...", zh: "内容正在更新中..." }[lang]}
        </div>
      </div>
    );
  }

  return (
    <div className="blog-stream">
      <h2 className="stream-title">{stream.title}</h2>
      <p className="stream-description">{stream.description}</p>
      <div className="blog-cards">
        {stream.articles && stream.articles.length > 0 ? (
          stream.articles.slice(0, 3).map((article, index) => (
            <BlogCard key={article.id || `${streamKey}-${index}`} article={article} />
          ))
        ) : (
          <div style={{
            textAlign: 'center',
            padding: '40px 20px',
            color: 'white',
            fontSize: '16px',
            fontWeight: '500',
            opacity: 0.8
          }}>
            {{ en: "Content is being updated...", zh: "内容正在更新中..." }[lang]}
          </div>
        )}
      </div>
    </div>
  );
};

const Blog = () => {
  const [loading, setLoading] = useState(true);
  const [blogConfig, setBlogConfig] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  // Use language context
  const { lang } = useContext(LanguageContext);

  // Function to get cached config from localStorage with language support
  const getCachedConfig = (language) => {
    try {
      const cached = localStorage.getItem(`blogConfig_${language}`);
      const timestamp = localStorage.getItem(`blogConfigTimestamp_${language}`);
      
      if (!cached || !timestamp) {
        return null;
      }
      
      const cacheTime = parseInt(timestamp);
      const now = Date.now();
      const sixHoursInMs = 6 * 60 * 60 * 1000; // 6 hours in milliseconds
      
      // Check if cache is older than 6 hours
      if (now - cacheTime > sixHoursInMs) {
        // Clear expired cache
        localStorage.removeItem(`blogConfig_${language}`);
        localStorage.removeItem(`blogConfigTimestamp_${language}`);
        return null;
      }
      
      return JSON.parse(cached);
    } catch (error) {
      console.error('Error reading cached config:', error);
      // Clear corrupted cache
      localStorage.removeItem(`blogConfig_${language}`);
      localStorage.removeItem(`blogConfigTimestamp_${language}`);
      return null;
    }
  };

  // Function to save config to localStorage with language support
  const saveConfigToCache = (config, language) => {
    try {
      localStorage.setItem(`blogConfig_${language}`, JSON.stringify(config));
      localStorage.setItem(`blogConfigTimestamp_${language}`, Date.now().toString());
    } catch (error) {
      console.error('Error saving config to cache:', error);
    }
  };

  useEffect(() => {
    const fetchBlogConfig = async () => {
      setLoading(true);
      
      // Check for cached config first (language-specific)
      const cachedConfig = getCachedConfig(lang);
      if (cachedConfig) {
        setBlogConfig(cachedConfig);
        setLastUpdated(cachedConfig.lastUpdated);
        setLoading(false);
        return;
      }
      
      try {
        // Fetch fresh config from repository
        const config = await fetchBlogConfigFromRepo(lang);
        
        if (config) {
          setBlogConfig(config);
          setLastUpdated(config.lastUpdated);
          // Save to cache after successful fetch
          saveConfigToCache(config, lang);
        } else {
          // Use fallback config
          console.log('⚠️ Using fallback config');
          const fallbackConfig = getFallbackConfig(lang);
          setBlogConfig(fallbackConfig);
          setLastUpdated(fallbackConfig.lastUpdated);
        }
        
      } catch (error) {
        console.error('Error fetching blog config:', error);
        // Use fallback config on error
        const fallbackConfig = getFallbackConfig(lang);
        setBlogConfig(fallbackConfig);
        setLastUpdated(fallbackConfig.lastUpdated);
      } finally {
        setLoading(false);
      }
    };

    fetchBlogConfig();
  }, [lang]); // Reload when language changes

  // Get the blog title from config
  const getBlogTitle = () => {
    if (!blogConfig || !blogConfig.title) {
      return { en: "My Blog", zh: "我的博客" }[lang] || "My Blog";
    }
    return blogConfig.title;
  };

  if (loading) {
    return (
      <section id="blog" className="blog-section">
        <div className="container">
          <h1 className="section-title" style={{ color: 'white' }}>{getBlogTitle()}</h1>
          <div className="blog-loading" style={{ color: 'white' }}>
            {{ en: "Loading blog articles...", zh: "正在加载博客文章..." }[lang]}
          </div>
        </div>
      </section>
    );
  }

  return (
    <section id="blog" className="blog-section">
      <div className="container">
        <div className="section-title"> 
          <h2 style={{ color: 'white' }}>{getBlogTitle()}</h2>
        </div>
        {lastUpdated && (
          <div style={{ 
            fontSize: '12px', 
            color: 'rgba(255, 255, 255, 0.6)', 
            marginBottom: '20px',
            textAlign: 'center',
            fontStyle: 'italic'
          }}>
            Last updated: {new Date(lastUpdated).toLocaleDateString()}
          </div>
        )}
        <div className="blog-streams">
          <BlogStream streamKey="life" stream={blogConfig?.streams?.life} loading={false} lang={lang} />
          <BlogStream streamKey="study" stream={blogConfig?.streams?.study} loading={false} lang={lang} />
          <BlogStream streamKey="work" stream={blogConfig?.streams?.work} loading={false} lang={lang} />
        </div>
      </div>
    </section>
  );
};

export default Blog;
