// Access Control Utility
// Manages user access levels and permissions

export const ACCESS_LEVELS = {
  PUBLIC: 'public',
  FRIENDS: 'friends', 
  OWNER: 'owner'
};

/**
 * Get the access level for a user based on their authentication info
 * @param {Object} user - User object from auth context
 * @returns {string} - Access level (public, friends, owner)
 */
export const getUserAccessLevel = (user) => {
  if (!user || !user.id) {
    return ACCESS_LEVELS.PUBLIC;
  }

  // Check if user is the owner
  if (isOwner(user)) {
    return ACCESS_LEVELS.OWNER;
  }

  // Check if user is a close friend
  if (isCloseFriend(user)) {
    return ACCESS_LEVELS.FRIENDS;
  }

  return ACCESS_LEVELS.PUBLIC;
};

/**
 * Check if user is the website owner
 * @param {Object} user - User object
 * @returns {boolean}
 */
export const isOwner = (user) => {
  if (!user) return false;

  const ownerEmail = process.env.REACT_APP_OWNER_EMAIL;
  const ownerGithubId = process.env.REACT_APP_OWNER_GITHUB_ID;
  const ownerGoogleId = process.env.REACT_APP_OWNER_GOOGLE_ID;

  // Check by email (works for both Google and GitHub if email is available)
  if (ownerEmail && user.email === ownerEmail) {
    return true;
  }

  // Check by provider-specific ID
  if (user.provider === 'github' && ownerGithubId && user.id.toString() === ownerGithubId) {
    return true;
  }

  if (user.provider === 'google' && ownerGoogleId && user.id === ownerGoogleId) {
    return true;
  }

  return false;
};

/**
 * Check if user is in the close friends list
 * @param {Object} user - User object
 * @returns {boolean}
 */
export const isCloseFriend = (user) => {
  if (!user) return false;

  // Get close friends lists from environment
  const friendsEmails = process.env.REACT_APP_CLOSE_FRIENDS_EMAILS?.split(',').map(e => e.trim()) || [];
  const friendsGithubIds = process.env.REACT_APP_CLOSE_FRIENDS_GITHUB_IDS?.split(',').map(id => id.trim()) || [];
  const friendsGoogleIds = process.env.REACT_APP_CLOSE_FRIENDS_GOOGLE_IDS?.split(',').map(id => id.trim()) || [];

  // Check by email
  if (user.email && friendsEmails.includes(user.email)) {
    return true;
  }

  // Check by provider-specific ID
  if (user.provider === 'github' && friendsGithubIds.includes(user.id.toString())) {
    return true;
  }

  if (user.provider === 'google' && friendsGoogleIds.includes(user.id)) {
    return true;
  }

  return false;
};

/**
 * Check if user has permission to access content with given visibility level
 * @param {Object} user - User object
 * @param {string} requiredLevel - Required access level
 * @returns {boolean}
 */
export const hasAccess = (user, requiredLevel) => {
  const userLevel = getUserAccessLevel(user);
  
  switch (requiredLevel) {
    case ACCESS_LEVELS.PUBLIC:
      return true;
    case ACCESS_LEVELS.FRIENDS:
      return userLevel === ACCESS_LEVELS.FRIENDS || userLevel === ACCESS_LEVELS.OWNER;
    case ACCESS_LEVELS.OWNER:
      return userLevel === ACCESS_LEVELS.OWNER;
    default:
      return false;
  }
};

/**
 * Get user display info for access level
 * @param {Object} user - User object
 * @param {string} lang - Language preference
 * @returns {Object} - Display information
 */
export const getAccessLevelDisplay = (user, lang = 'en') => {
  const level = getUserAccessLevel(user);
  
  const displays = {
    [ACCESS_LEVELS.PUBLIC]: {
      en: { label: 'Public User', icon: '👤', description: 'Standard access' },
      zh: { label: '普通用户', icon: '👤', description: '标准访问权限' }
    },
    [ACCESS_LEVELS.FRIENDS]: {
      en: { label: 'Close Friend', icon: '👥', description: 'Special access to private content' },
      zh: { label: '密友', icon: '👥', description: '私人内容特殊访问权限' }
    },
    [ACCESS_LEVELS.OWNER]: {
      en: { label: 'Website Owner', icon: '👑', description: 'Full administrative access' },
      zh: { label: '网站主人', icon: '👑', description: '完全管理访问权限' }
    }
  };

  return displays[level][lang] || displays[level].en;
};

/**
 * Load hidden configuration safely
 * @returns {Object|null} - Hidden configuration or null if not available
 */
export const loadHiddenConfig = async () => {
  try {
    // Import from src/config directory
    const { loadHiddenConfig: loadConfig } = await import('../config/hiddenConfig.js');
    return await loadConfig();
  } catch (error) {
    console.log('Hidden config not available:', error.message);
    return null;
  }
};

/**
 * Get user info for logging/notification purposes
 * @param {Object} user - User object
 * @returns {string} - Formatted user info
 */
export const getUserInfoForLogging = (user) => {
  if (!user) return 'Anonymous user';
  
  const parts = [];
  if (user.name) parts.push(`Name: ${user.name}`);
  if (user.email) parts.push(`Email: ${user.email}`);
  if (user.provider) parts.push(`Provider: ${user.provider}`);
  if (user.id) parts.push(`ID: ${user.id}`);
  
  return parts.join(', ') || 'Authenticated user (limited info)';
};

/**
 * Get client information for logging
 * @returns {Object} - Client information
 */
export const getClientInfo = () => {
  return {
    userAgent: navigator.userAgent,
    language: navigator.language,
    platform: navigator.platform,
    timestamp: new Date().toISOString(),
    url: window.location.href,
    referrer: document.referrer
  };
}; 