// Backend API utility
const isDevelopment = process.env.NODE_ENV === 'development';
const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

const getBackendEndpoint = () => {
  const fallback = isDevelopment || isLocalhost
    ? 'http://127.0.0.1:8082'
    : 'https://api.tomzhao.me';
  return (process.env.REACT_APP_BACKEND_ENDPOINT || fallback).replace(/\/$/, '');
};

/**
 * Make a request to the backend API
 * @param {string} endpoint - API endpoint (e.g., '/messages', '/easter-egg/stats')
 * @param {object} options - Fetch options (method, headers, body, etc.)
 * @returns {Promise<Response>} - Fetch response
 */
export const backendRequest = async (endpoint, options = {}) => {
  const backendUrl = getBackendEndpoint();
  const fullUrl = `${backendUrl}${endpoint}`;
  
  try {
    const response = await fetch(fullUrl, {
      ...options,
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
    
    if (!response.ok) {
      console.error(`❌ Backend request failed: ${response.status} ${response.statusText}`);
      throw new Error(`Backend request failed: ${response.status} ${response.statusText}`);
    }
    
    return response;
  } catch (error) {
    console.error(`❌ Backend request error for ${endpoint}:`, error);
    throw error;
  }
};

/**
 * GET request to backend
 * @param {string} endpoint - API endpoint
 * @returns {Promise<any>} - Parsed JSON response
 */
export const backendGet = async (endpoint) => {
  const response = await backendRequest(endpoint, {
    method: 'GET',
  });
  return response.json();
};

/**
 * POST request to backend
 * @param {string} endpoint - API endpoint
 * @param {object} data - Request body data
 * @returns {Promise<any>} - Parsed JSON response
 */
export const backendPost = async (endpoint, data) => {
  const response = await backendRequest(endpoint, {
    method: 'POST',
    body: JSON.stringify(data),
  });
  return response.json();
};

/**
 * PUT request to backend
 * @param {string} endpoint - API endpoint
 * @param {object} data - Request body data
 * @returns {Promise<any>} - Parsed JSON response
 */
export const backendPut = async (endpoint, data) => {
  const response = await backendRequest(endpoint, {
    method: 'PUT',
    body: JSON.stringify(data),
  });
  return response.json();
};

/**
 * DELETE request to backend
 * @param {string} endpoint - API endpoint
 * @returns {Promise<any>} - Parsed JSON response
 */
export const backendDelete = async (endpoint) => {
  const response = await backendRequest(endpoint, {
    method: 'DELETE',
  });
  return response.json();
};

// Export for testing and debugging
export { getBackendEndpoint };