import React, { useState, useEffect, useContext } from 'react';
import { useAuth } from './AuthContext';
import { LanguageContext } from './LanguageProvider';
import { backendGet, backendPut } from '../../utils/backendApi';

const Analytics = () => {
  const { user, accessLevel } = useAuth();
  const { lang } = useContext(LanguageContext);
  const [requests, setRequests] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const translations = {
    en: {
      title: "Easter Egg Analytics",
      stats: "Statistics",
      requests: "Access Requests",
      totalRequests: "Total Requests",
      requestsToday: "Requests Today",
      approvedRequests: "Approved",
      pendingRequests: "Pending",
      uniqueRegions: "Unique Regions",
      noRequests: "No requests yet",
      loading: "Loading...",
      error: "Error loading data",
      approve: "Approve",
      deny: "Deny",
      pending: "Pending",
      approved: "Approved",
      denied: "Denied",
      updateStatus: "Update Status",
      loginMethod: "Login Method",
      username: "Username/Email",
      region: "Region",
      timestamp: "Timestamp",
      status: "Status",
      actions: "Actions"
    },
    zh: {
      title: "彩蛋分析",
      stats: "统计信息",
      requests: "访问请求",
      totalRequests: "总请求数",
      requestsToday: "今日请求",
      approvedRequests: "已批准",
      pendingRequests: "待处理",
      uniqueRegions: "独立地区",
      noRequests: "暂无请求",
      loading: "加载中...",
      error: "加载数据出错",
      approve: "批准",
      deny: "拒绝",
      pending: "待处理",
      approved: "已批准",
      denied: "已拒绝",
      updateStatus: "更新状态",
      loginMethod: "登录方式",
      username: "用户名/邮箱",
      region: "地区",
      timestamp: "时间",
      status: "状态",
      actions: "操作"
    }
  };

  const t = translations[lang] || translations.en;

  // Only show analytics if user is the owner (you can customize this check)
  const isOwner = user && (
    user.email === 'tomzhao.me@gmail.com' ||
    user.email === 'zhao.xuan@imperial.ac.uk' ||
    accessLevel === 'owner'
  );

  useEffect(() => {
    if (isOwner) {
      loadAnalytics();
    }
  }, [isOwner]);

  const loadAnalytics = async () => {
    setLoading(true);
    setError(null);

    try {
      // Load stats
      const statsData = await backendGet('/easter-egg/stats');
      setStats(statsData);

      // Load requests
      const requestsData = await backendGet('/easter-egg/requests');
      setRequests(requestsData.requests || []);

    } catch (err) {
      console.error('Error loading analytics:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const updateRequestStatus = async (requestId, newStatus) => {
    try {
      await backendPut(`/easter-egg/${requestId}/status`, { status: newStatus });
      // Reload data
      loadAnalytics();
    } catch (err) {
      console.error('Error updating status:', err);
      alert(`Error updating status: ${err.message}`);
    }
  };

  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    return date.toLocaleDateString(lang === 'zh' ? 'zh-CN' : 'en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved': return '#10b981';
      case 'denied': return '#ef4444';
      case 'pending': return '#f59e0b';
      default: return '#6b7280';
    }
  };

  // Don't render if user is not owner
  if (!isOwner) {
    return null;
  }

  return (
    <div style={{
      background: 'rgba(255, 255, 255, 0.1)',
      backdropFilter: 'blur(20px)',
      WebkitBackdropFilter: 'blur(20px)',
      border: '1px solid rgba(255, 255, 255, 0.2)',
      borderRadius: '20px',
      padding: '30px',
      margin: '20px 0',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.3)'
    }}>
      <h3 style={{
        color: 'white',
        fontSize: '24px',
        fontWeight: '600',
        marginBottom: '20px',
        textAlign: 'center'
      }}>
        {t.title}
      </h3>

      {loading && (
        <div style={{ color: 'white', textAlign: 'center', padding: '20px' }}>
          {t.loading}
        </div>
      )}

      {error && (
        <div style={{ color: '#ef4444', textAlign: 'center', padding: '20px' }}>
          {t.error}: {error}
        </div>
      )}

      {!loading && !error && (
        <>
          {/* Statistics */}
          {stats && (
            <div style={{ marginBottom: '30px' }}>
              <h4 style={{ color: 'white', fontSize: '18px', marginBottom: '15px' }}>
                {t.stats}
              </h4>
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
                gap: '15px'
              }}>
                <div style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '15px',
                  borderRadius: '10px',
                  textAlign: 'center'
                }}>
                  <div style={{ color: 'white', fontSize: '24px', fontWeight: 'bold' }}>
                    {stats.total_requests}
                  </div>
                  <div style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '12px' }}>
                    {t.totalRequests}
                  </div>
                </div>
                <div style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '15px',
                  borderRadius: '10px',
                  textAlign: 'center'
                }}>
                  <div style={{ color: 'white', fontSize: '24px', fontWeight: 'bold' }}>
                    {stats.today_requests}
                  </div>
                  <div style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '12px' }}>
                    {t.requestsToday}
                  </div>
                </div>
                <div style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '15px',
                  borderRadius: '10px',
                  textAlign: 'center'
                }}>
                  <div style={{ color: '#10b981', fontSize: '24px', fontWeight: 'bold' }}>
                    {stats.approved_requests}
                  </div>
                  <div style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '12px' }}>
                    {t.approvedRequests}
                  </div>
                </div>
                <div style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '15px',
                  borderRadius: '10px',
                  textAlign: 'center'
                }}>
                  <div style={{ color: '#f59e0b', fontSize: '24px', fontWeight: 'bold' }}>
                    {stats.pending_requests}
                  </div>
                  <div style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '12px' }}>
                    {t.pendingRequests}
                  </div>
                </div>
                <div style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '15px',
                  borderRadius: '10px',
                  textAlign: 'center'
                }}>
                  <div style={{ color: '#8b5cf6', fontSize: '24px', fontWeight: 'bold' }}>
                    {stats.unique_regions}
                  </div>
                  <div style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '12px' }}>
                    {t.uniqueRegions}
                  </div>
                </div>

              </div>
            </div>
          )}

          {/* Requests Table */}
          <div>
            <h4 style={{ color: 'white', fontSize: '18px', marginBottom: '15px' }}>
              {t.requests}
            </h4>
            {requests.length === 0 ? (
              <div style={{ color: 'rgba(255, 255, 255, 0.7)', textAlign: 'center', padding: '20px' }}>
                {t.noRequests}
              </div>
            ) : (
              <div style={{ overflowX: 'auto' }}>
                <table style={{
                  width: '100%',
                  borderCollapse: 'collapse',
                  background: 'rgba(255, 255, 255, 0.05)',
                  borderRadius: '10px',
                  overflow: 'hidden'
                }}>
                  <thead>
                    <tr style={{ background: 'rgba(255, 255, 255, 0.1)' }}>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.loginMethod}</th>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.username}</th>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.region}</th>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.timestamp}</th>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.status}</th>
                      <th style={{ color: 'white', padding: '12px', textAlign: 'left' }}>{t.actions}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {requests.map((request) => (
                      <tr key={request.id} style={{ borderBottom: '1px solid rgba(255, 255, 255, 0.1)' }}>
                        <td style={{ color: 'white', padding: '12px' }}>
                          {request.login_method === 'github' ? 'GitHub' : 'Google'}
                        </td>
                        <td style={{ color: 'white', padding: '12px' }}>{request.username_or_email}</td>
                                                  <td style={{ color: 'rgba(255, 255, 255, 0.7)', padding: '12px', fontSize: '12px' }}>
                           {request.ip_address}
                          </td>
                        <td style={{ color: 'rgba(255, 255, 255, 0.7)', padding: '12px', fontSize: '12px' }}>
                          {formatDate(request.timestamp)}
                        </td>
                        <td style={{ padding: '12px' }}>
                          <span style={{
                            color: getStatusColor(request.status),
                            fontWeight: 'bold',
                            fontSize: '12px'
                          }}>
                            {t[request.status]}
                          </span>
                        </td>
                        <td style={{ padding: '12px' }}>
                          <span style={{
                            color: 'rgba(255, 255, 255, 0.5)',
                            fontSize: '10px',
                            fontStyle: 'italic'
                          }}>
                            {request.status === 'pending' ? 'Actions disabled' : '-'}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default Analytics;