import React, { useState, useEffect, useCallback } from 'react';
import { getUserInfoForLogging, getClientInfo, loadHiddenConfig, isCloseFriend, isOwner } from '../../utils/accessControl';
import { useAuth } from './AuthContext';
import { backendPost } from '../../utils/backendApi';

const EasterEgg = ({ lang }) => {
  const [clickCount, setClickCount] = useState(0);
  const [isTriggered, setIsTriggered] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [easterEggConfig, setEasterEggConfig] = useState(null);
  const [isRequestSent, setIsRequestSent] = useState(false);
  const { user } = useAuth();

  // Load Easter egg configuration
  useEffect(() => {
    const loadConfig = async () => {
      try {
        const hiddenConfig = await loadHiddenConfig();
        console.log('🔍 Hidden config loaded:', hiddenConfig);
        if (hiddenConfig?.easterEgg) {
          console.log('🎯 Easter egg config found:', hiddenConfig.easterEgg);
          setEasterEggConfig(hiddenConfig.easterEgg);
        } else {
          console.warn('⚠️ No easter egg configuration found in hidden config, using fallback');
          // Fallback configuration for development/testing
          const fallbackConfig = {
            trigger: {
              clicks: 5,
              element: "intro-title"
            },
            message: {
              en: "🎉 You found the secret! There's hidden content on this site. Would you like to request access?",
              zh: "🎉 你发现了秘密！这个网站上有隐藏内容。你想要申请访问权限吗？"
            },
            emailTemplate: {
              subject: "Hidden Content Access Request",
              template: "User {userInfo} has requested access to hidden content. IP: {ip}, Time: {timestamp}"
            }
          };
          console.log('🔄 Using fallback easter egg config:', fallbackConfig);
          setEasterEggConfig(fallbackConfig);
        }
      } catch (error) {
        console.error('❌ Error loading easter egg config:', error);
        // Use fallback even on error
        const fallbackConfig = {
          trigger: {
            clicks: 5,
            element: "intro-title"
          },
          message: {
            en: "🎉 You found the secret! There's hidden content on this site. Would you like to request access?",
            zh: "🎉 你发现了秘密！这个网站上有隐藏内容。你想要申请访问权限吗？"
          },
          emailTemplate: {
            subject: "Hidden Content Access Request",
            template: "User {userInfo} has requested access to hidden content. IP: {ip}, Time: {timestamp}"
          }
        };
        console.log('🔄 Using fallback easter egg config due to error:', fallbackConfig);
        setEasterEggConfig(fallbackConfig);
      }
    };
    loadConfig();
  }, []);

  // Reset click count after timeout
  useEffect(() => {
    if (clickCount > 0 && !isTriggered) {
      const timer = setTimeout(() => {
        setClickCount(0);
      }, 3000); // Reset after 3 seconds of inactivity
      
      return () => clearTimeout(timer);
    }
  }, [clickCount, isTriggered]);

  // Handle click on trigger element
  const handleTriggerClick = useCallback((event) => {
    console.log('🖱️ Easter egg trigger clicked!', event.target);
    
    if (isTriggered) {
      console.log('⚠️ Easter egg already triggered, ignoring click');
      return;
    }
    
    if (!easterEggConfig) {
      console.log('⚠️ No easter egg config, ignoring click');
      return;
    }

    const newClickCount = clickCount + 1;
    setClickCount(newClickCount);

    console.log(`🔢 Easter Egg Click: ${newClickCount}/${easterEggConfig.trigger.clicks}`);

    // Visual feedback for each click
    const element = event.target;
    element.style.transition = 'transform 0.1s ease';
    element.style.transform = 'scale(0.95)';
    setTimeout(() => {
      element.style.transform = 'scale(1)';
      setTimeout(() => {
        element.style.transition = '';
      }, 100);
    }, 100);

    if (newClickCount >= easterEggConfig.trigger.clicks) {
      console.log('🎉 Easter Egg Triggered! Showing modal...');
      setIsTriggered(true);
      setShowModal(true);
    } else {
      console.log(`🔢 Need ${easterEggConfig.trigger.clicks - newClickCount} more clicks`);
    }
  }, [clickCount, isTriggered, easterEggConfig]);

  // Send access request to backend
  const sendAccessRequest = async () => {
    try {
      if (!user) {
        alert(lang === 'zh' ? '请先登录！' : 'Please log in first!');
        return;
      }

      const clientInfo = getClientInfo();
      
      // Determine login method and username/email based on user provider
      const loginMethod = user.provider || 'google'; // fallback to google if provider not set
      const usernameOrEmail = loginMethod === 'github' 
        ? (user.login || user.name || user.email) // For GitHub, prefer username
        : user.email; // For Google, use email
      
      const requestData = {
        login_method: loginMethod,
        username_or_email: usernameOrEmail,
        url: clientInfo.url
      };

      console.log('📧 Sending easter egg request to backend:', requestData);
      
      try {
        const result = await backendPost('/easter-egg/request', requestData);
        console.log('✅ Easter egg request sent successfully:', result);
        setIsRequestSent(true);
        
        // Auto-close modal after showing success
        setTimeout(() => {
          setShowModal(false);
        }, 3000);
      } catch (fetchError) {
        console.error('❌ Error sending easter egg request:', fetchError);
        alert(lang === 'zh' ? '网络错误，请稍后重试。' : 'Network error. Please try again later.');
      }

    } catch (error) {
      console.error('Error sending access request:', error);
      alert(lang === 'zh' ? '发送请求时出错。' : 'Error sending request.');
    }
  };

  // Set up trigger element click listener with retry mechanism
  useEffect(() => {
    if (!easterEggConfig) {
      console.log('🔍 No easter egg config, skipping event listener setup');
      return;
    }

    console.log('🎯 Setting up easter egg click listener for element:', easterEggConfig.trigger.element);

    const setupListener = () => {
      const triggerElement = document.getElementById(easterEggConfig.trigger.element);
      console.log('🔍 Looking for trigger element:', easterEggConfig.trigger.element, 'Found:', !!triggerElement);
      
      if (triggerElement) {
        console.log('✅ Easter egg trigger element found, attaching click listener');
        triggerElement.addEventListener('click', handleTriggerClick);
        triggerElement.style.cursor = 'pointer';
        
        return () => {
          console.log('🧹 Cleaning up easter egg event listener');
          triggerElement.removeEventListener('click', handleTriggerClick);
        };
      } else {
        console.warn('⚠️ Easter egg trigger element not found, retrying in 1 second...');
        // Retry after a delay to ensure DOM is ready
        const retryTimer = setTimeout(() => {
          setupListener();
        }, 1000);
        
        return () => clearTimeout(retryTimer);
      }
    };

    // Initial setup
    const cleanup = setupListener();
    
    return cleanup;
  }, [easterEggConfig, handleTriggerClick]);

  if (!easterEggConfig || !showModal) {
    return null;
  }

  const message = easterEggConfig.message[lang] || easterEggConfig.message.en;
  
  // Check if user already has access (is owner or close friend)
  const userHasAccess = user && (isOwner(user) || isCloseFriend(user));

  // Add CSS animations
  const animationStyles = `
    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }
    
    @keyframes slideUp {
      from { 
        opacity: 0; 
        transform: translateY(30px) scale(0.95); 
      }
      to { 
        opacity: 1; 
        transform: translateY(0) scale(1); 
      }
    }
  `;

  return (
    <>
      <style>{animationStyles}</style>
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 999999,
      backdropFilter: 'blur(20px)',
      WebkitBackdropFilter: 'blur(20px)',
      animation: 'fadeIn 0.3s ease-out'
    }}>
      <div style={{
        background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.15) 0%, rgba(255, 255, 255, 0.05) 100%)',
        backdropFilter: 'blur(30px) saturate(180%)',
        WebkitBackdropFilter: 'blur(30px) saturate(180%)',
        padding: '50px',
        borderRadius: '25px',
        maxWidth: '520px',
        width: '90%',
        textAlign: 'center',
        boxShadow: `
          0 25px 75px rgba(0, 0, 0, 0.4),
          0 10px 30px rgba(0, 0, 0, 0.2),
          inset 0 1px 0 rgba(255, 255, 255, 0.4),
          inset 0 -1px 0 rgba(0, 0, 0, 0.1)
        `,
        border: '1px solid rgba(255, 255, 255, 0.3)',
        position: 'relative',
        overflow: 'hidden',
        animation: 'slideUp 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
        zIndex: 1000000
      }}>
        {/* Glass effect overlay - creates the frosted glass appearance */}
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.2) 0%, transparent 50%)',
          pointerEvents: 'none',
          borderRadius: '25px'
        }} />
        
        {/* Content background for better text readability */}
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.1)',
          pointerEvents: 'none',
          borderRadius: '25px'
        }} />
        
        <div style={{
          fontSize: '64px',
          marginBottom: '25px',
          position: 'relative',
          zIndex: 10,
          filter: 'drop-shadow(0 4px 20px rgba(0, 0, 0, 0.8))'
        }}>
          🎉
        </div>
          
          <h3 style={{
            margin: '0 0 20px 0',
            color: '#ffffff',
            fontSize: '24px',
            fontWeight: '700',
            textShadow: '0 2px 12px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.9)',
            position: 'relative',
            zIndex: 10
          }}>
            {lang === 'zh' ? '恭喜！' : 'Congratulations!'}
          </h3>
          
          <p style={{
            color: '#f8f9fa',
            lineHeight: '1.6',
            marginBottom: '30px',
            fontSize: '16px',
            fontWeight: '500',
            textShadow: '0 2px 8px rgba(0, 0, 0, 0.7), 0 1px 2px rgba(0, 0, 0, 0.8)',
            position: 'relative',
            zIndex: 10
          }}>
            {message}
          </p>

          {!isRequestSent ? (
            <>
              {!user ? (
                <div style={{ marginBottom: '20px' }}>
                  <p style={{
                    color: '#fbbf24',
                    fontSize: '16px',
                    fontWeight: '600',
                    textShadow: '0 2px 8px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.9)',
                    position: 'relative',
                    zIndex: 10,
                    marginBottom: '15px'
                  }}>
                    ⚠️ {lang === 'zh' ? '请先登录以申请访问权限' : 'Please log in first to request access'}
                  </p>
                </div>
              ) : userHasAccess ? (
                <div style={{ marginBottom: '20px' }}>
                  <div style={{
                    color: '#10b981',
                    fontSize: '18px',
                    fontWeight: '700',
                    marginBottom: '15px',
                    textShadow: '0 2px 8px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.9)',
                    position: 'relative',
                    zIndex: 10
                  }}>
                    ✅ {lang === 'zh' ? '访问权限已开启！' : 'Access Granted!'}
                  </div>
                  <p style={{
                    color: '#f8f9fa',
                    fontSize: '14px',
                    fontWeight: '500',
                    textShadow: '0 2px 8px rgba(0, 0, 0, 0.7), 0 1px 2px rgba(0, 0, 0, 0.8)',
                    position: 'relative',
                    zIndex: 10,
                    marginBottom: '20px'
                  }}>
                    {lang === 'zh' 
                      ? '您已经拥有隐藏内容的访问权限。探索网站的特殊功能吧！' 
                      : 'You already have access to hidden content. Explore the special features of the site!'
                    }
                  </p>
                  <button
                    onClick={() => {
                      setShowModal(false);
                      setClickCount(0);
                      setIsTriggered(false);
                      setIsRequestSent(false);
                      console.log('🔄 Easter egg reset after access granted close');
                    }}
                    style={{
                      background: 'linear-gradient(135deg, rgba(16, 185, 129, 0.9) 0%, rgba(5, 150, 105, 0.9) 100%)',
                      color: 'white',
                      border: '1px solid rgba(255, 255, 255, 0.3)',
                      padding: '12px 24px',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      fontSize: '16px',
                      fontWeight: '600',
                      transition: 'all 0.2s ease',
                      textShadow: '0 1px 3px rgba(0, 0, 0, 0.5)',
                      boxShadow: '0 4px 15px rgba(16, 185, 129, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)',
                      backdropFilter: 'blur(10px)',
                      WebkitBackdropFilter: 'blur(10px)',
                      position: 'relative',
                      zIndex: 10
                    }}
                    onMouseEnter={(e) => {
                      e.target.style.background = 'linear-gradient(135deg, rgba(16, 185, 129, 1) 0%, rgba(5, 150, 105, 1) 100%)';
                      e.target.style.transform = 'translateY(-1px)';
                      e.target.style.boxShadow = '0 6px 20px rgba(16, 185, 129, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3)';
                    }}
                    onMouseLeave={(e) => {
                      e.target.style.background = 'linear-gradient(135deg, rgba(16, 185, 129, 0.9) 0%, rgba(5, 150, 105, 0.9) 100%)';
                      e.target.style.transform = 'translateY(0)';
                      e.target.style.boxShadow = '0 4px 15px rgba(16, 185, 129, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)';
                    }}
                  >
                    {lang === 'zh' ? '好的' : 'Got it'}
                  </button>
                </div>
              ) : (
                <div style={{ display: 'flex', gap: '15px', justifyContent: 'center' }}>
                  <button
                    onClick={sendAccessRequest}
                    style={{
                      background: 'linear-gradient(135deg, rgba(0, 123, 255, 0.9) 0%, rgba(0, 86, 179, 0.9) 100%)',
                      color: 'white',
                      border: '1px solid rgba(255, 255, 255, 0.3)',
                      padding: '12px 24px',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      fontSize: '16px',
                      fontWeight: '600',
                      transition: 'all 0.2s ease',
                      textShadow: '0 1px 3px rgba(0, 0, 0, 0.5)',
                      boxShadow: '0 4px 15px rgba(0, 123, 255, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)',
                      backdropFilter: 'blur(10px)',
                      WebkitBackdropFilter: 'blur(10px)',
                      position: 'relative',
                      zIndex: 10
                    }}
                    onMouseEnter={(e) => {
                      e.target.style.background = 'linear-gradient(135deg, rgba(0, 123, 255, 1) 0%, rgba(0, 86, 179, 1) 100%)';
                      e.target.style.transform = 'translateY(-1px)';
                      e.target.style.boxShadow = '0 6px 20px rgba(0, 123, 255, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.3)';
                    }}
                    onMouseLeave={(e) => {
                      e.target.style.background = 'linear-gradient(135deg, rgba(0, 123, 255, 0.9) 0%, rgba(0, 86, 179, 0.9) 100%)';
                      e.target.style.transform = 'translateY(0)';
                      e.target.style.boxShadow = '0 4px 15px rgba(0, 123, 255, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)';
                    }}
                  >
                    {lang === 'zh' ? '申请访问' : 'Request Access'}
                  </button>
                  
                  <button
                    onClick={() => {
                      // Reset Easter egg state when "Maybe Later" is clicked
                      setShowModal(false);
                      setClickCount(0);
                      setIsTriggered(false);
                      setIsRequestSent(false);
                      console.log('🔄 Easter egg reset after "Maybe Later"');
                    }}
                    style={{
                      backgroundColor: 'rgba(255, 255, 255, 0.1)',
                      color: '#ffffff',
                      border: '2px solid rgba(255, 255, 255, 0.3)',
                      padding: '12px 24px',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      fontSize: '16px',
                      fontWeight: '600',
                      transition: 'all 0.2s ease',
                      textShadow: '0 2px 6px rgba(0, 0, 0, 0.7), 0 1px 2px rgba(0, 0, 0, 0.8)',
                      backdropFilter: 'blur(10px)',
                      WebkitBackdropFilter: 'blur(10px)',
                      position: 'relative',
                      zIndex: 10
                    }}
                    onMouseEnter={(e) => {
                      e.target.style.borderColor = 'rgba(255, 255, 255, 0.5)';
                      e.target.style.color = '#ffffff';
                      e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
                    }}
                    onMouseLeave={(e) => {
                      e.target.style.borderColor = 'rgba(255, 255, 255, 0.3)';
                      e.target.style.color = '#ffffff';
                      e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                    }}
                  >
                    {lang === 'zh' ? '稍后再说' : 'Maybe Later'}
                  </button>
                </div>
              )}
              
              {/* Close button for non-logged in users */}
              {!user && (
                <button
                  onClick={() => {
                    setShowModal(false);
                    setClickCount(0);
                    setIsTriggered(false);
                    setIsRequestSent(false);
                    console.log('🔄 Easter egg reset after close');
                  }}
                  style={{
                    backgroundColor: 'rgba(255, 255, 255, 0.1)',
                    color: '#ffffff',
                    border: '2px solid rgba(255, 255, 255, 0.3)',
                    padding: '12px 24px',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '16px',
                    fontWeight: '600',
                    transition: 'all 0.2s ease',
                    textShadow: '0 2px 6px rgba(0, 0, 0, 0.7), 0 1px 2px rgba(0, 0, 0, 0.8)',
                    backdropFilter: 'blur(10px)',
                    WebkitBackdropFilter: 'blur(10px)',
                    position: 'relative',
                    zIndex: 10,
                    marginTop: '10px'
                  }}
                  onMouseEnter={(e) => {
                    e.target.style.borderColor = 'rgba(255, 255, 255, 0.5)';
                    e.target.style.color = '#ffffff';
                    e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.borderColor = 'rgba(255, 255, 255, 0.3)';
                    e.target.style.color = '#ffffff';
                    e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                  }}
                >
                  {lang === 'zh' ? '关闭' : 'Close'}
                </button>
              )}
            </>
          ) : (
            <div>
              <div style={{
                color: '#4ade80',
                fontSize: '18px',
                fontWeight: '700',
                marginBottom: '15px',
                textShadow: '0 2px 8px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.9)',
                position: 'relative',
                zIndex: 10
              }}>
                ✅ {lang === 'zh' ? '请求已发送！' : 'Request Sent!'}
              </div>
              <p style={{
                color: '#f8f9fa',
                fontSize: '14px',
                fontWeight: '500',
                textShadow: '0 2px 8px rgba(0, 0, 0, 0.7), 0 1px 2px rgba(0, 0, 0, 0.8)',
                position: 'relative',
                zIndex: 10
              }}>
                {lang === 'zh' 
                  ? '我会尽快审核您的申请。' 
                  : "I'll review your request as soon as possible."
                }
              </p>
                      </div>
        )}
      </div>
    </div>
    </>
  );
};

export default EasterEgg; 