import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import * as lodash from 'lodash';
import React, { useEffect, useState, useCallback, useContext } from 'react';
import Particles from 'react-tsparticles';
import { loadSlim } from "tsparticles-slim";
import { imgBaseUrl } from '../../App';
import '../../css/homepage.css';
import { useCommonConfig, useLocalizedConfig } from '../Common/Config';
import SocialLinks from '../Common/SocialLinks';
import particleConfig from './particle.config.json';
import { BackgroundContext } from '../Common/BackgroundContext';
import { LanguageContext } from '../Common/LanguageProvider';
import EasterEgg from '../Common/EasterEgg';

function PhotoCredit({ backgroundImage, language = 'en' }) {
    if (!backgroundImage?.description) return null;

    const description = backgroundImage.description[language] || backgroundImage.description.en;
    const lines = description.split('|').map(line => line.trim());
    
    return (
        <div className="photo-credit">
            <div className="photo-credit-content">
                <div style={{ display: 'flex', alignItems: 'center', marginBottom: '4px' }}>
                    <FontAwesomeIcon icon={['fas', 'camera']} style={{ marginRight: '6px', opacity: 0.7, fontSize: '12px' }} />
                    <span style={{ fontSize: '11px', fontWeight: '500' }}>Photo Credit</span>
                </div>
                {lines.map((line, index) => (
                    <div key={index} style={{ 
                        fontSize: '10px', 
                        lineHeight: '1.3',
                        marginBottom: index < lines.length - 1 ? '2px' : '0',
                        opacity: 0.9
                    }}>
                        {line}
                    </div>
                ))}
            </div>
        </div>
    );
}

const Intro = () => {
    const common = useCommonConfig();
    const intro = useLocalizedConfig("intro.config.json");
    const [bg, setBg] = useState();
    const [currentBgImage, setCurrentBgImage] = useState(null);
    const [textPosition, setTextPosition] = useState("center");
    const [overlayOpacity, setOverlayOpacity] = useState(0.45);
    const { setCurrentBackground } = useContext(BackgroundContext);
    const { lang } = useContext(LanguageContext);
    
    useEffect(() => {
        if (common?.intro_images) {
            // Get recently used backgrounds from localStorage
            const recentBgs = JSON.parse(localStorage.getItem('recentBgs') || '[]');
            const maxRecent = 3; // Number of recent backgrounds to avoid

            // Filter out recently used backgrounds
            const availableBgs = common.intro_images.filter(bg => 
                !recentBgs.includes(bg.path)
            );

            // If all backgrounds have been used recently, reset the history
            const selectedBg = availableBgs.length > 0 
                ? lodash.sample(availableBgs)
                : lodash.sample(common.intro_images);

            // Update recent backgrounds list
            const newRecentBgs = [selectedBg.path, ...recentBgs].slice(0, maxRecent);
            localStorage.setItem('recentBgs', JSON.stringify(newRecentBgs));

            setBg(selectedBg.path);
            setCurrentBgImage(selectedBg);
            setTextPosition(selectedBg.position);
            // set primary color
            const stylesheet = document.styleSheets[0];
            stylesheet.insertRule(`.highlight { color: ${selectedBg.color}; }`);
        }
    }, [common]);

    // Animate overlay opacity on scroll
    useEffect(() => {
        const handleScroll = () => {
            const scrollY = window.scrollY;
            const fadeDistance = window.innerHeight * 0.7; // fade out over 70% of viewport height
            let opacity = 0.45 * (1 - Math.min(scrollY / fadeDistance, 1));
            setOverlayOpacity(opacity);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const particlesInit = useCallback(async engine => {
        await loadSlim(engine);
    }, []);

    const particlesLoaded = useCallback(async container => {
        await console.log(container);
    }, []);

    return (
        <section className="intro-section" id="home">
            <div className="intro-background" style={bg && { backgroundImage: "url(" + imgBaseUrl + bg + ")" }}>
                <Particles
                    id="tsparticles" 
                    init={particlesInit} 
                    loaded={particlesLoaded}
                    options={particleConfig} 
                />
            </div>
            <div 
                className="intro-overlay"
                style={{ opacity: overlayOpacity }}
            />
            <div className="intro-content spad">
                <div className="container">
                    <div className={`intro-inner ${textPosition}`}>
                        <div>
                            <h2 id="intro-title" dangerouslySetInnerHTML={{ __html: intro?.title }}></h2>
                            <h3 style={{ whiteSpace: "pre-wrap" }}>{intro?.subtitle}</h3>
                            <div style={{ height: 50 }}></div>
                            {
                                intro?.links?.map(({icon, html}, index) => (
                                    <h3 key={index} style={{ color: "white" }}>
                                        <FontAwesomeIcon icon={icon} /> 
                                        <span dangerouslySetInnerHTML={{__html: html}}></span>
                                    </h3>
                                ))
                            }
                            <div style={{ height: 50 }}></div>
                            <SocialLinks 
                                linkClassName="highlight" 
                                currentColor={currentBgImage?.color}
                            />
                        </div>
                    </div>
                </div>
            </div>
            <PhotoCredit backgroundImage={currentBgImage} language={lang} />
            <EasterEgg lang={lang} />
        </section>
    );
}

export default Intro;
