import React, { useContext } from 'react';
import { LanguageContext } from '../Common/LanguageProvider';
import MessageBoard from '../Common/MessageBoard';
import '../../css/homepage.css';

function Board() {
    const { lang } = useContext(LanguageContext);

    const translations = {
        en: {
            title: "Community Board",
            subtitle: "Share your thoughts with the community"
        },
        zh: {
            title: "社区留言板",
            subtitle: "与社区分享您的想法"
        }
    };

    const t = translations[lang] || translations.en;

    return (
        <section className="board-section spad" id="board">
            <div className="section-title" style={{ textAlign: 'center', marginBottom: '30px' }}>
                <h2 style={{ color: '#fff', fontSize: '36px', fontWeight: '600', marginBottom: '15px' }}>{t.title}</h2>
                <p style={{ color: 'rgba(255, 255, 255, 0.8)', fontSize: '16px', margin: '0' }}>{t.subtitle}</p>
            </div>
            <MessageBoard />
        </section>
    );
}

export default Board; 