import Isotope from 'isotope-layout';
import React, { forwardRef, useEffect, useState, useContext } from 'react';
import { Link } from 'react-router-dom';
import { imgBaseUrl } from '../../App';
import { useLocalizedConfig } from '../Common/Config';
import { LanguageContext } from '../Common/LanguageProvider';
import { useAuth } from '../Common/AuthContext';
import { loadHiddenConfig, ACCESS_LEVELS } from '../../utils/accessControl';

function FilterItem(props) {
  return (
    <li className={"filter" + (props.active ? " active" : "")} onClick={props.onClick}>{props.title}</li>
  );
}

const PhotoGalleryItem = forwardRef((props, ref) => {
  const classSetting = props.position + " " + props.tag;
  const bgImageStyle = { backgroundImage: 'url(' + imgBaseUrl + props.image + ')' }

  return <div className={classSetting} ref={ref} style={{ padding: "0 5px" }}>
    {/* <Link to={props.link}> */}
      <a href={props.link} className="portfolio-item set-bg" style={bgImageStyle}>
        <div className="portfolio-text">
          <h2>{props.title}</h2>
          <p>{props.location}</p>
        </div>
      </a>
    {/* </Link> */}
  </div>
});

function PhotoGallery() {
  const photo = useLocalizedConfig("photo.config.json");
  const [filter, setFilter] = useState("*");
  const [isotope, setIsotope] = useState(undefined);
  const [activity, setActivity] = useState();
  const [blurAmount, setBlurAmount] = useState(0);
  const [hiddenAlbums, setHiddenAlbums] = useState(null);
  const [combinedFilters, setCombinedFilters] = useState([]);
  const { lang } = useContext(LanguageContext);
  const { accessLevel, hasAccess } = useAuth();

  // Load hidden albums for authorized users
  useEffect(() => {
    const loadHiddenAlbums = async () => {
      if (hasAccess(ACCESS_LEVELS.FRIENDS)) {
        const hiddenConfig = await loadHiddenConfig();
        if (hiddenConfig?.photoAlbums) {
          setHiddenAlbums(hiddenConfig.photoAlbums);
        }
      }
    };
    loadHiddenAlbums();
  }, [hasAccess]);

  // Combine public and private filters
  useEffect(() => {
    const filters = [];
    
    // Add public filters
    if (photo?.tags) {
      filters.push(...photo.tags.map(tag => ({
        ...tag,
        type: 'public'
      })));
    }
    
    // Add private filters for authorized users
    if (hiddenAlbums?.albums && hasAccess(ACCESS_LEVELS.FRIENDS)) {
      hiddenAlbums.albums.forEach(album => {
        filters.push({
          label: album.filter,
          name: `🔒 ${album.title[lang] || album.title.en}`,
          type: 'private'
        });
      });
    }
    
    setCombinedFilters(filters);
  }, [photo, hiddenAlbums, hasAccess, lang]);

  useEffect(() => {
    if (photo) {
      if (!isotope) {
        setTimeout(() => {
          const node = document.querySelector(".isotope_items");
          setIsotope(new Isotope(node, { layoutMode: "fitRows" }));
        }, 100);
      }
      
      setActivity({ ...photo, display_number: activity ? activity.display_number : photo.display_number })
    }
  }, [photo]);

  useEffect(() => {
    if (isotope) {
      setIsotope(undefined);
      setTimeout(() => {
        setIsotope(new Isotope(".isotope_items", { layoutMode: "fitRows" }));
      }, 100);
    }
  }, [activity]);

  // Animate blur on scroll
  useEffect(() => {
    const handleScroll = () => {
      const section = document.querySelector('.portfolio-section');
      const activitySection = document.querySelector('.activity-section');
      if (!section || !activitySection) return;

      const sectionRect = section.getBoundingClientRect();
      const activityRect = activitySection.getBoundingClientRect();
      const viewportHeight = window.innerHeight;

      // Only start transition when we're approaching the PhotoGallery section
      if (sectionRect.top > viewportHeight * 0.6) {
        setBlurAmount(0); // No blur before reaching PhotoGallery
        return;
      }

      // Calculate transition based on distance between Activity and PhotoGallery sections
      const transitionStart = activityRect.bottom;
      const transitionEnd = sectionRect.top;
      const transitionDistance = transitionEnd - transitionStart;

      // Calculate blur based on scroll position between sections
      if (sectionRect.top < 0) {
        setBlurAmount(10); // Significantly increased maximum blur when PhotoGallery is fully in view
      } else {
        const progress = Math.min(
          Math.max(
            (viewportHeight - sectionRect.top) / transitionDistance,
            0
          ),
          1
        );
        setBlurAmount(progress * 10); // Smooth transition from 0 to 10px blur
      }
    };

    // Add scroll event listener with passive option for better performance
    window.addEventListener('scroll', handleScroll, { passive: true });
    // Initial calculation
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const onChangeFilter = (filterLabel) => {
    isotope.arrange({
      filter: filterLabel
    })
    isotope.layout();
  }

  return (
    <section className="portfolio-section spad" id="gallery">
      <div className="page-blur-overlay" style={{ 
        backdropFilter: `blur(${blurAmount}px)`,
        WebkitBackdropFilter: `blur(${blurAmount}px)`,
        transform: `translate3d(0, 0, 0)`
      }} />
      <div className="portfolio-content" style={{
        position: 'relative',
        zIndex: 10000
      }}>
        <div className="section-title">
          <h2>{photo && photo.title}</h2>
        </div>
        <div>
          <ul className="portfolio-filter">

            {/* Combined public and private filters */}
            {combinedFilters.map((item, index) => (
              <FilterItem 
                key={`${item.label}-${index}`} 
                active={filter === item.label}
                onClick={() => {
                  setFilter(item.label);
                  onChangeFilter(item.label);
                }}
                filter={item.label}
                title={item.name} 
              />
            ))}
          </ul>
        </div>
        {photo &&
          <div className="row isotope_items">
            {/* Render public albums */}
            {activity && activity.covers.slice(0, activity.display_number).map(item => (
              <PhotoGalleryItem key={`public-${item.title}_${activity.display_number}`}
                id={item.id}
                tag={item.filter}
                image={item.image}
                title={item.title}
                location={item.location}
                position={item.position}
                link={item.link} />
            ))}
            
            {/* Render private albums for authorized users */}
            {hiddenAlbums?.albums && hasAccess(ACCESS_LEVELS.FRIENDS) && 
              hiddenAlbums.albums.map(album => (
                <PhotoGalleryItem 
                  key={`private-${album.id}`}
                  id={album.id}
                  tag={album.filter}
                  image={album.cover}
                  title={album.title[lang] || album.title.en}
                  location={album.location}
                  position="col-lg-4 col-md-6"
                  link={`#hidden-album-${album.id}`}
                />
              ))
            }
          </div>
        }
      </div>
    </section>
  );
}

export default PhotoGallery;