import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { useAuth } from './AuthContext';
import { ACCESS_LEVELS } from '../../utils/accessControl';

const WebsiteAnalytics = ({ lang }) => {
  const [analyticsData, setAnalyticsData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [refreshInterval, setRefreshInterval] = useState(null);
  const { hasAccess } = useAuth();

  // Check access level - but keep hooks above the conditional return
  const hasOwnerAccess = hasAccess(ACCESS_LEVELS.OWNER);

  const fetchAnalyticsData = async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Mock data for demonstration - replace with real analytics API
      const mockData = {
        visitors: {
          today: Math.floor(Math.random() * 100) + 50,
          yesterday: Math.floor(Math.random() * 80) + 40,
          thisWeek: Math.floor(Math.random() * 500) + 200,
          thisMonth: Math.floor(Math.random() * 2000) + 1000
        },
        pageViews: {
          today: Math.floor(Math.random() * 200) + 100,
          yesterday: Math.floor(Math.random() * 150) + 80,
          thisWeek: Math.floor(Math.random() * 1000) + 500,
          thisMonth: Math.floor(Math.random() * 4000) + 2000
        },
        topPages: [
          { path: '/', views: Math.floor(Math.random() * 100) + 50, title: 'Homepage' },
          { path: '/#blog', views: Math.floor(Math.random() * 50) + 20, title: 'Blog Section' },
          { path: '/#gallery', views: Math.floor(Math.random() * 80) + 30, title: 'Photo Gallery' },
          { path: '/#contact', views: Math.floor(Math.random() * 40) + 15, title: 'Chat Section' }
        ],
        countries: [
          { name: 'United States', visitors: Math.floor(Math.random() * 50) + 20, flag: '🇺🇸' },
          { name: 'United Kingdom', visitors: Math.floor(Math.random() * 30) + 15, flag: '🇬🇧' },
          { name: 'China', visitors: Math.floor(Math.random() * 40) + 10, flag: '🇨🇳' },
          { name: 'Germany', visitors: Math.floor(Math.random() * 25) + 8, flag: '🇩🇪' },
          { name: 'Canada', visitors: Math.floor(Math.random() * 20) + 5, flag: '🇨🇦' }
        ],
        realtimeVisitors: Math.floor(Math.random() * 10) + 1,
        lastUpdated: new Date().toISOString()
      };

      // If real API is configured, use it
      if (process.env.REACT_APP_ANALYTICS_API_URL) {
        try {
          const response = await fetch(process.env.REACT_APP_ANALYTICS_API_URL, {
            headers: {
              'Authorization': `Bearer ${process.env.REACT_APP_ANALYTICS_API_KEY}`,
              'Content-Type': 'application/json'
            }
          });
          
          if (response.ok) {
            const realData = await response.json();
            setAnalyticsData(realData);
          } else {
            throw new Error('Failed to fetch real analytics data');
          }
        } catch (apiError) {
          console.warn('Analytics API failed, using mock data:', apiError);
          setAnalyticsData(mockData);
        }
      } else {
        setAnalyticsData(mockData);
      }
    } catch (error) {
      setError(error.message);
      console.error('Error fetching analytics:', error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (hasOwnerAccess) {
      fetchAnalyticsData();
      
      // Set up auto-refresh
      const interval = setInterval(fetchAnalyticsData, 30000); // Refresh every 30 seconds
      setRefreshInterval(interval);
      
      return () => {
        if (interval) clearInterval(interval);
      };
    }
  }, [hasOwnerAccess]);

  const StatCard = ({ title, value, icon, color = '#007bff' }) => (
    <div style={{
      backgroundColor: 'rgba(255, 255, 255, 0.1)',
      backdropFilter: 'blur(10px)',
      WebkitBackdropFilter: 'blur(10px)',
      border: '1px solid rgba(255, 255, 255, 0.2)',
      borderRadius: '12px',
      padding: '20px',
      textAlign: 'center',
      color: 'white',
      minWidth: '140px'
    }}>
      <div style={{ fontSize: '24px', marginBottom: '8px', color }}>
        <FontAwesomeIcon icon={icon} />
      </div>
      <div style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '4px' }}>
        {value}
      </div>
      <div style={{ fontSize: '12px', opacity: 0.8 }}>
        {title}
      </div>
    </div>
  );

  // Only show to owner
  if (!hasOwnerAccess) {
    return null;
  }

  if (error) {
    return (
      <section style={{
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        color: 'white',
        padding: '40px 20px',
        textAlign: 'center'
      }}>
        <h3>Analytics Error</h3>
        <p>Failed to load analytics data: {error}</p>
        <button onClick={fetchAnalyticsData} style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          padding: '10px 20px',
          borderRadius: '6px',
          cursor: 'pointer'
        }}>
          Retry
        </button>
      </section>
    );
  }

  return (
    <section style={{
      backgroundColor: 'rgba(0, 0, 0, 0.9)',
      color: 'white',
      padding: '60px 20px',
      position: 'relative'
    }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '40px'
        }}>
          <h2 style={{ margin: 0, fontSize: '28px' }}>
            👑 {lang === 'zh' ? '网站分析' : 'Website Analytics'}
          </h2>
          
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <div style={{
              backgroundColor: 'rgba(34, 197, 94, 0.2)',
              border: '1px solid rgba(34, 197, 94, 0.3)',
              borderRadius: '20px',
              padding: '6px 12px',
              fontSize: '12px',
              display: 'flex',
              alignItems: 'center',
              gap: '6px'
            }}>
              <div style={{
                width: '8px',
                height: '8px',
                backgroundColor: '#22c55e',
                borderRadius: '50%',
                animation: 'pulse 1s infinite'
              }} />
              {analyticsData?.realtimeVisitors || 0} {lang === 'zh' ? '在线访客' : 'Live Visitors'}
            </div>
            
            <button
              onClick={fetchAnalyticsData}
              disabled={isLoading}
              style={{
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.2)',
                borderRadius: '6px',
                padding: '8px 12px',
                color: 'white',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                fontSize: '14px',
                opacity: isLoading ? 0.5 : 1
              }}
            >
              <FontAwesomeIcon icon={isLoading ? 'spinner' : 'sync-alt'} spin={isLoading} />
              {' '}{lang === 'zh' ? '刷新' : 'Refresh'}
            </button>
          </div>
        </div>

        {analyticsData && (
          <>
            {/* Main Stats */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
              gap: '20px',
              marginBottom: '40px'
            }}>
              <StatCard
                title={lang === 'zh' ? '今日访客' : 'Today Visitors'}
                value={analyticsData.visitors.today}
                icon="users"
                color="#22c55e"
              />
              <StatCard
                title={lang === 'zh' ? '今日浏览' : 'Today Views'}
                value={analyticsData.pageViews.today}
                icon="eye"
                color="#3b82f6"
              />
              <StatCard
                title={lang === 'zh' ? '本周访客' : 'Week Visitors'}
                value={analyticsData.visitors.thisWeek}
                icon="chart-line"
                color="#f59e0b"
              />
              <StatCard
                title={lang === 'zh' ? '本月浏览' : 'Month Views'}
                value={analyticsData.pageViews.thisMonth}
                icon="chart-bar"
                color="#ef4444"
              />
            </div>

            {/* Detailed Analytics */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
              gap: '30px'
            }}>
              {/* Top Pages */}
              <div style={{
                backgroundColor: 'rgba(255, 255, 255, 0.05)',
                borderRadius: '12px',
                padding: '25px',
                border: '1px solid rgba(255, 255, 255, 0.1)'
              }}>
                <h4 style={{ marginBottom: '20px', fontSize: '18px' }}>
                  📊 {lang === 'zh' ? '热门页面' : 'Top Pages'}
                </h4>
                {analyticsData.topPages.map((page, index) => (
                  <div key={index} style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '8px 0',
                    borderBottom: index < analyticsData.topPages.length - 1 ? '1px solid rgba(255, 255, 255, 0.1)' : 'none'
                  }}>
                    <span style={{ fontSize: '14px' }}>{page.title}</span>
                    <span style={{ 
                      backgroundColor: 'rgba(59, 130, 246, 0.3)',
                      padding: '2px 8px',
                      borderRadius: '12px',
                      fontSize: '12px'
                    }}>
                      {page.views}
                    </span>
                  </div>
                ))}
              </div>

              {/* Top Countries */}
              <div style={{
                backgroundColor: 'rgba(255, 255, 255, 0.05)',
                borderRadius: '12px',
                padding: '25px',
                border: '1px solid rgba(255, 255, 255, 0.1)'
              }}>
                <h4 style={{ marginBottom: '20px', fontSize: '18px' }}>
                  🌍 {lang === 'zh' ? '访客地区' : 'Visitor Countries'}
                </h4>
                {analyticsData.countries.map((country, index) => (
                  <div key={index} style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '8px 0',
                    borderBottom: index < analyticsData.countries.length - 1 ? '1px solid rgba(255, 255, 255, 0.1)' : 'none'
                  }}>
                    <span style={{ fontSize: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <span style={{ fontSize: '16px' }}>{country.flag}</span>
                      {country.name}
                    </span>
                    <span style={{ 
                      backgroundColor: 'rgba(34, 197, 94, 0.3)',
                      padding: '2px 8px',
                      borderRadius: '12px',
                      fontSize: '12px'
                    }}>
                      {country.visitors}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            <div style={{
              textAlign: 'center',
              marginTop: '30px',
              fontSize: '12px',
              opacity: 0.6
            }}>
              {lang === 'zh' ? '最后更新：' : 'Last Updated: '}
              {new Date(analyticsData.lastUpdated).toLocaleString()}
            </div>
          </>
        )}
      </div>

      <style jsx>{`
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.5; }
        }
      `}</style>
    </section>
  );
};

export default WebsiteAnalytics; 