import React, { useEffect, useState, useContext } from 'react';
import { imgBaseUrl } from '../../App';
import { useLocalizedConfig } from '../Common/Config';
import ReadMoreText from '../Common/ReadMoreText';
import { LanguageContext } from '../Common/LanguageProvider';

function ActivityItem(props) {
  return (
    <div className="activity-item wow fadeInUp" data-wow-delay="0.3s">
      <div className="activity-content">
        <h2 style={{ color: "black" }}>{props.activityName}</h2>
        <h3>{props.activityTime}</h3>
        <p>
          <ReadMoreText text={props.activityDescription} />
          {" "}
          <div>
            {props.activityLink ? <a href={props.activityLink.link} style={{ fontWeight: "bold" }}>{props.activityLink.text}</a> : null}
          </div>
        </p>
      </div>
      {props.activityImage &&
        <div className="activity-image">
          <img loading="lazy" src={imgBaseUrl + props.activityImage} style={{ width: "100%", padding: `${props.imagePadding}px` }} alt="Something went wrong" />
        </div>
      }
    </div>
  );
}

function Activity() {
  // Function to get current number of columns based on window width
  const getCurrentCol = () => {
    if (window.innerWidth > 991) {
      return 4;
    } else if (window.innerWidth > 767) {
      return 2;
    }
    return 1;
  };

  const [activity, setActivity] = useState();
  const [displayNumber, setDisplayNumber] = useState(getCurrentCol());
  const [displayIndexOrder, setDisplayIndexOrder] = useState([]);
  const config = useLocalizedConfig("activity.config.json");
  const { lang } = useContext(LanguageContext);

  useEffect(() => {
    setActivity(config);
  }, [config]);

  // Function to arrange items in horizontal-first order
  const arrangeItemsHorizontally = (items, columns) => {
    if (!items) return [];
    const result = [];
    const rows = Math.ceil(items.length / columns);

    for (let c = 0; c < columns; c++) {
      for (let r = 0; r < rows; r++) {
        const index = r * columns + c;
        if (index < items.length) {
          result.push(index);
        }
      }
    }

    return result;
  };

  useEffect(() => {

  }, []);

  // Update displayIndexOrder whenever displayNumber changes
  useEffect(() => {
    const handleResize = () => {
      if (activity) {
        const newCols = getCurrentCol();
        setDisplayNumber(Math.max(newCols, displayNumber));
        setDisplayIndexOrder(arrangeItemsHorizontally(
          Array.from({ length: Math.min(displayNumber, activity.items.length) }, (_, i) => i),
          newCols
        ));
      }
    };

    if (activity) {
      const indices = Array.from({ length: Math.min(displayNumber, activity.items.length) }, (_, i) => i);
      setDisplayIndexOrder(arrangeItemsHorizontally(indices, getCurrentCol()));
    }

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [activity, displayNumber]);

  return (
    <section className="activity-section spad" id="update">
      <div className="container">
        <div className="section-title">
          <h2>{activity && activity.title}</h2>
        </div>
        <div className="activity-grid">
          {activity && displayIndexOrder.map((index) => (
            <ActivityItem
              key={index}
              activityName={activity.items[index].title}
              activityTime={activity.items[index].time}
              activityDescription={activity.items[index].description}
              activityImage={activity.items[index].image}
              activityLink={activity.items[index].link}
              imagePadding={activity.items[index].padding}
            />
          ))}
        </div>
        {activity && displayNumber < activity.items.length && (
          <div className="load-more-container">
            <button
              className="site-btn"
              onClick={() => {
                const newDisplayNumber = displayNumber + getCurrentCol();
                setDisplayNumber(newDisplayNumber);
              }}
            >
              {{ en: "View Previous Activities & Updates", zh: "点击查看历史动态/项目" }[lang]}
            </button>
          </div>
        )}
      </div>
    </section>
  );
}

export default Activity;