import React, { useState, useEffect, useContext } from 'react';
import { useAuth } from './AuthContext';
import { LanguageContext } from './LanguageProvider';
import { backendGet, backendPost } from '../../utils/backendApi';
import './MessageBoard.css';

const MessageBoard = () => {
  const { user } = useAuth();
  const { lang } = useContext(LanguageContext);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [userMessageCount, setUserMessageCount] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);



  const translations = {
    en: {
      title: "Message Board",
      placeholder: "Share your thoughts...",
      submit: "Post Message",
      loginRequired: "Please log in to post messages",
      dailyLimit: "Daily limit reached (3 messages per day)",
      messageCount: "messages today",
      noMessages: "No messages yet. Be the first to share!",
      loading: "Loading messages...",
      submitting: "Posting...",
      postedOn: "Posted on",
      from: "from"
    },
    zh: {
      title: "留言板",
      placeholder: "分享您的想法...",
      submit: "发布留言",
      loginRequired: "请登录后发布留言",
      dailyLimit: "今日留言数量已达上限（每日3条）",
      messageCount: "条今日留言",
      noMessages: "暂无留言，来做第一个留言的人吧！",
      loading: "加载留言中...",
      submitting: "发布中...",
      postedOn: "发布于",
      from: "来自"
    }
  };

  const t = translations[lang] || translations.en;

  useEffect(() => {
    loadMessages();
  }, []);

  useEffect(() => {
    if (user) {
      const loadUserMessageCount = async () => {
        try {
          const data = await backendGet('/messages/user-count');
          setUserMessageCount(data.count);
        } catch (error) {
          console.error('Error loading user message count:', error);
          setUserMessageCount(0);
        }
      };
      loadUserMessageCount();
    } else {
      setUserMessageCount(0); // Reset count when no user
    }
  }, [user]);

  const loadMessages = async () => {
    setIsLoading(true);
    try {
      const data = await backendGet('/messages');
      setMessages(Array.isArray(data) ? data : data.messages || []);
    } catch (error) {
      console.error('Error loading messages:', error);
      setMessages([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!user || !newMessage.trim() || userMessageCount >= 3 || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const messageData = {
        message: newMessage.trim()
      };

      const newMessageWithId = await backendPost('/messages', messageData);
      setMessages(prev => [newMessageWithId, ...prev]);
      setUserMessageCount(prev => prev + 1);
      setNewMessage('');
      
    } catch (error) {
      console.error('Error posting message:', error);
      alert('Failed to post message. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    return date.toLocaleDateString(lang === 'zh' ? 'zh-CN' : 'en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const canPostMessage = user && userMessageCount < 3;

  return (
    <div className="message-board">
      <div className="message-board-header">
        <h3>{t.title}</h3>
        {user && (
          <div className="user-stats">
            <span className="message-count">
              {userMessageCount}/3 {t.messageCount}
            </span>
          </div>
        )}
      </div>

      {/* Message Form */}
      {user ? (
        <form onSubmit={handleSubmit} className="message-form">
          <div className="form-user-info">
            <img 
              src={user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.id || user.email}`}
              alt={user.name || user.email}
              className="form-avatar"
            />
            <span className="form-username">
              {user.name || user.email}
            </span>
          </div>
          <textarea
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder={t.placeholder}
            maxLength={500}
            disabled={!canPostMessage || isSubmitting}
            className="message-input"
          />
          <div className="form-footer">
            <span className="char-count">{newMessage.length}/500</span>
            <button 
              type="submit" 
              disabled={!canPostMessage || !newMessage.trim() || isSubmitting}
              className="submit-button"
            >
              {isSubmitting ? t.submitting : t.submit}
            </button>
          </div>
          {userMessageCount >= 3 && (
            <div className="limit-warning">{t.dailyLimit}</div>
          )}
        </form>
      ) : (
        <div className="login-prompt">
          <p>{t.loginRequired}</p>
        </div>
      )}

      {/* Messages List */}
      <div className="messages-container">
        {isLoading ? (
          <div className="loading">{t.loading}</div>
        ) : messages.length === 0 ? (
          <div className="no-messages">{t.noMessages}</div>
        ) : (
          <div className="messages-list">
            {messages.map((message) => (
              <div key={message.id} className="message-item">
                <div className="message-header">
                  <img 
                    src={message.avatar}
                    alt={message.username}
                    className="message-avatar"
                  />
                  <div className="message-meta">
                    <span className="message-username">
                      {message.username}
                    </span>
                    <span className="message-timestamp">
                      {t.postedOn} {formatDate(message.timestamp)}
                    </span>
                    <span className="message-ip">
                      {t.from} {message.ip_address}
                    </span>
                  </div>
                </div>
                <div className="message-content">
                  {message.message}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default MessageBoard; 