import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import React, { useState, useEffect } from 'react';
import { useCommonConfig } from './Config';
import { useAuth } from './AuthContext';
import { ACCESS_LEVELS } from '../../utils/accessControl';
import { loadHiddenConfig } from '../../config/hiddenConfig';

function SocialLinks({ 
    containerClassName = "social-links",
    linkClassName = "",
    linkStyle = {},
    containerStyle = {},
    forceWhite = false, // Simple prop to force white color for footer
    currentColor = null // Color from config (e.g., from intro background)
}) {
    const common = useCommonConfig();
    const { hasAccess } = useAuth();
    const [hiddenSocialLinks, setHiddenSocialLinks] = useState([]);

    // Load hidden social links for authorized users
    useEffect(() => {
        const loadHiddenSocial = async () => {
            if (hasAccess(ACCESS_LEVELS.FRIENDS)) {
                try {
                    const hiddenConfig = await loadHiddenConfig();
                    console.log('📱 Loading hidden social links. Hidden config:', hiddenConfig);
                    
                    if (hiddenConfig?.socialMedia) {
                        const hiddenLinks = Object.values(hiddenConfig.socialMedia).filter(link => {
                            // Validate link structure
                            if (!link || !link.link) {
                                console.warn('⚠️ Invalid hidden social link:', link);
                                return false;
                            }
                            
                            // Check if user has access to this social link
                            if (link.accessLevel === 'friends') {
                                return hasAccess(ACCESS_LEVELS.FRIENDS);
                            } else if (link.accessLevel === 'owner') {
                                return hasAccess(ACCESS_LEVELS.OWNER);
                            }
                            return true; // Default to showing if no specific access level
                        });
                        
                        console.log('✅ Hidden social links loaded:', hiddenLinks);
                        setHiddenSocialLinks(hiddenLinks);
                    } else {
                        console.log('ℹ️ No hidden social media found in config');
                        setHiddenSocialLinks([]);
                    }
                } catch (error) {
                    console.error('❌ Error loading hidden social links:', error);
                    setHiddenSocialLinks([]);
                }
            } else {
                console.log('🔒 No access to hidden social links');
                setHiddenSocialLinks([]); // Clear hidden links if no access
            }
        };

        loadHiddenSocial();
    }, [hasAccess]);

    const renderIcon = (iconData) => {
        try {
            // Comprehensive validation
            if (!iconData || typeof iconData !== 'object') {
                console.warn('⚠️ Invalid iconData provided to renderIcon:', iconData);
                return <span>❓</span>; // Fallback icon
            }

            console.log('🎨 Rendering icon for:', iconData);

            // Handle custom SVG icons
            if (iconData.customImage && typeof iconData.customImage === 'string') {
                let svgStyle = {
                    width: '1em',
                    height: '1em',
                    display: 'inline-block',
                    verticalAlign: 'middle',
                };

                if (forceWhite) {
                    svgStyle.filter = 'brightness(0) invert(1)';
                } else if (currentColor) {
                    svgStyle.backgroundColor = currentColor;
                    svgStyle.WebkitMask = `url(${iconData.customImage}) no-repeat center`;
                    svgStyle.mask = `url(${iconData.customImage}) no-repeat center`;
                    svgStyle.WebkitMaskSize = 'contain';
                    svgStyle.maskSize = 'contain';
                    
                    return (
                        <div
                            style={svgStyle}
                            aria-label={iconData.name || 'Social Icon'}
                            className="custom-svg-icon highlight-svg"
                        />
                    );
                }

                return (
                    <img 
                        src={iconData.customImage} 
                        alt={iconData.name || 'Social Icon'}
                        style={svgStyle}
                        className="custom-svg-icon"
                    />
                );
            }
            
            // Handle FontAwesome icons with comprehensive validation
            if (iconData.icon && typeof iconData.icon === 'string' && iconData.icon.trim()) {
                try {
                    console.log('🔍 Processing FontAwesome icon:', iconData.icon);
                    
                    const iconString = iconData.icon.trim();
                    if (!iconString.includes(',')) {
                        console.warn('⚠️ Invalid FontAwesome icon format (missing comma):', iconString);
                        return <span>🔗</span>;
                    }
                    
                    const parts = iconString.split(',');
                    if (parts.length !== 2) {
                        console.warn('⚠️ Invalid FontAwesome icon format (wrong number of parts):', iconString);
                        return <span>🔗</span>;
                    }
                    
                    const iconType = parts[0]?.trim();
                    const iconName = parts[1]?.trim();
                    
                    if (!iconType || !iconName) {
                        console.warn('⚠️ Invalid FontAwesome icon parts:', { iconType, iconName });
                        return <span>🔗</span>;
                    }
                    
                    console.log('✅ Valid FontAwesome icon:', { iconType, iconName });
                    return <FontAwesomeIcon icon={[iconType, iconName]} />;
                    
                } catch (splitError) {
                    console.error('❌ Error parsing FontAwesome icon:', iconData.icon, splitError);
                    return <span>🔗</span>;
                }
            }
            
            // Fallback for missing or invalid icons
            console.warn('🔗 Using fallback icon for:', iconData);
            return <span>🔗</span>;
            
        } catch (generalError) {
            console.error('❌ General error in renderIcon:', generalError, 'iconData:', iconData);
            return <span>⚠️</span>; // Error fallback
        }
    };

    // Combine public and hidden social links
    const allSocialLinks = [
        ...(common?.social_media || []),
        ...hiddenSocialLinks
    ];

    // Debug logging
    console.log('🔗 All social links:', allSocialLinks);
    console.log('📋 Common social media:', common?.social_media);
    console.log('🔐 Hidden social links:', hiddenSocialLinks);

    return (
        <div className={containerClassName} style={containerStyle}>
            {allSocialLinks.filter(item => item && item.link).map((item, index) => {
                return (
                    <a 
                        key={`${item.name || 'social'}-${index}`} 
                        href={item.link} 
                        className={linkClassName}
                        style={linkStyle}
                        target="_blank"
                        rel="noopener noreferrer"
                    >
                        {renderIcon(item)}
                    </a>
                );
            })}
        </div>
    );
}

export default SocialLinks; 