import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import React, { useCallback, useContext, useState, useEffect, useRef } from 'react';
import '../../css/homepage.css';
import { LanguageContext } from './LanguageProvider';
import { useAuth } from './AuthContext';
import LoginModal from './LoginModal';

function Navigation() {
    const { lang, setLang } = useContext(LanguageContext);
    const { user, isAuthenticated, signOut, getAccessLevelDisplay, accessLevel } = useAuth();
    const [showLoginModal, setShowLoginModal] = useState(false);
    const [showUserMenu, setShowUserMenu] = useState(false);
    const [showHoverHint, setShowHoverHint] = useState(false);
    const userMenuRef = useRef(null);

    // Function to detect which section is currently in view
    const getCurrentSection = useCallback(() => {
        const sections = ['home', 'blog', 'update', 'gallery', 'board', 'contact'];
        const viewportHeight = window.innerHeight;
        const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        
        let currentSection = 'home'; // default
        let maxVisibleArea = 0;
        
        sections.forEach(sectionId => {
            const element = document.getElementById(sectionId);
            if (element) {
                const rect = element.getBoundingClientRect();
                const elementTop = rect.top + scrollTop;
                const elementBottom = elementTop + rect.height;
                
                // Calculate visible area of the section
                const visibleTop = Math.max(elementTop, scrollTop);
                const visibleBottom = Math.min(elementBottom, scrollTop + viewportHeight);
                const visibleArea = Math.max(0, visibleBottom - visibleTop);
                
                // If this section has more visible area, it's the current section
                if (visibleArea > maxVisibleArea) {
                    maxVisibleArea = visibleArea;
                    currentSection = sectionId;
                }
            }
        });
        
        return currentSection;
    }, []);

    const switchLanguage = useCallback(() => {
        // Detect current section before language switch
        const currentSection = getCurrentSection();
        
        // Switch language first
        setLang(lang === "en" ? "zh" : "en");
        
        // Wait longer for language change to fully render, then instantly scroll to section
        setTimeout(() => {
            offsetTo(currentSection, true); // true for instant scroll
        }, 200);
    }, [lang, setLang, getCurrentSection]);

    // Click outside detection to close user menu
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
                setShowUserMenu(false);
                setShowHoverHint(false);
            }
        };

        if (showUserMenu) {
            document.addEventListener('mousedown', handleClickOutside);
        }

        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [showUserMenu]);

    const handleLoginClick = () => {
        setShowLoginModal(true);
    };

    const handleLogout = async () => {
        await signOut();
        setShowUserMenu(false);
    };

    const closeLoginModal = () => {
        setShowLoginModal(false);
    };

    const toggleUserMenu = () => {
        setShowUserMenu(!showUserMenu);
        setShowHoverHint(false); // Hide hint when menu is toggled
    };

    // Handle avatar hover for hint
    const handleAvatarMouseEnter = () => {
        if (!showUserMenu) {
            setShowHoverHint(true);
        }
    };

    const handleAvatarMouseLeave = () => {
        setShowHoverHint(false);
    };

    // Handle click outside to close menu
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
                setShowUserMenu(false);
                setShowHoverHint(false);
            }
        };

        if (showUserMenu) {
            document.addEventListener('mousedown', handleClickOutside);
        }

        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [showUserMenu]);

    function offsetTo(id, instant = false) {
        try {
            const targetElement = document.getElementById(id);
            if (targetElement) {
                if (instant) {
                    // Instant scroll for language switching
                    targetElement.scrollIntoView({ 
                        behavior: 'instant', 
                        block: 'start',
                        inline: 'nearest'
                    });
                } else {
                    // Smooth scrolling for regular navigation
                    targetElement.scrollIntoView({ 
                        behavior: 'smooth', 
                        block: 'start',
                        inline: 'nearest'
                    });
                }
            } else {
                console.warn(`Section with id "${id}" not found`);
            }
        } catch (error) {
            console.error('Error scrolling to section:', error);
            // Fallback to original method
            try {
                let el = document.documentElement;
                let st = document.getElementById(id);
                if (st) {
                    el.scrollTop = st.offsetTop;
                }
            } catch (fallbackError) {
                console.error('Fallback scroll method also failed:', fallbackError);
            }
        }
    }

    return (
        <>
            <style>
                {`
                    @keyframes fadeIn {
                        from { opacity: 0; transform: translateX(-50%) translateY(-5px); }
                        to { opacity: 1; transform: translateX(-50%) translateY(0); }
                    }
                `}
            </style>
            <div className={"nav-bar"} >
                <ul>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("home")}}><FontAwesomeIcon icon="home" /></h6></li>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("blog")}}>{{ en: "Blog", zh: "博客" }[lang]}</h6></li>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("update")}}>{{ en: "Proj", zh: "动态" }[lang]}</h6></li>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("gallery")}}>{{ en: "Photo", zh: "照片库" }[lang]}</h6></li>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("board")}}>{{ en: "Board", zh: "留言板" }[lang]}</h6></li>
                    <li><h6 style={{ color: "white" }} onClick={() => {offsetTo("contact")}}>{{ en: "Chat", zh: "聊天" }[lang]}</h6></li>
                    <li><h6 style={{ color: "white" }} onClick={switchLanguage}>{{ en: "中", zh: "En" }[lang]}</h6></li>
                    
                    {/* Login/User Avatar */}
                    <li style={{ position: 'relative' }}>
                        {isAuthenticated ? (
                            <div 
                                ref={userMenuRef}
                                className="user-avatar-container"
                                style={{ 
                                    position: 'relative',
                                    display: 'inline-block'
                                }}
                            >
                                {/* Avatar Button */}
                                <div
                                    style={{ 
                                        cursor: 'pointer',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        height: '25px', // Match the login button height
                                        minHeight: '25px', // Ensure minimum height
                                        padding: '0 4px',
                                        position: 'relative'
                                    }} 
                                    onClick={toggleUserMenu}
                                    onMouseEnter={handleAvatarMouseEnter}
                                    onMouseLeave={handleAvatarMouseLeave}
                                    title={showHoverHint ? (lang === 'zh' ? '点击我' : 'Click me') : user?.name}
                                >
                                    {user?.avatar && (
                                        <img 
                                            src={user.avatar} 
                                            alt="User Avatar"
                                            className="user-avatar-img"
                                            style={{
                                                width: '25px', // Default desktop size
                                                height: '25px',
                                                borderRadius: '50%',
                                                border: `2px solid ${showHoverHint ? 'rgba(255, 255, 255, 0.6)' : 'rgba(255, 255, 255, 0.3)'}`,
                                                transition: 'all 0.2s ease',
                                                boxShadow: showUserMenu ? '0 0 10px rgba(255, 255, 255, 0.3)' : showHoverHint ? '0 0 8px rgba(255, 255, 255, 0.2)' : 'none',
                                                display: 'block', // Ensure proper display
                                                transform: showHoverHint ? 'scale(1.05)' : 'scale(1)'
                                            }}
                                        />
                                    )}
                                    
                                    {/* Hover hint */}
                                    {showHoverHint && !showUserMenu && (
                                        <div
                                            style={{
                                                position: 'absolute',
                                                top: '100%',
                                                left: '50%',
                                                transform: 'translateX(-50%)',
                                                marginTop: '8px',
                                                background: 'rgba(0, 0, 0, 0.8)',
                                                backdropFilter: 'blur(10px)',
                                                WebkitBackdropFilter: 'blur(10px)',
                                                color: 'white',
                                                padding: '4px 8px',
                                                borderRadius: '6px',
                                                fontSize: '12px',
                                                fontWeight: '500',
                                                whiteSpace: 'nowrap',
                                                zIndex: 1001,
                                                border: '1px solid rgba(255, 255, 255, 0.2)',
                                                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
                                                animation: 'fadeIn 0.2s ease-out'
                                            }}
                                        >
                                            {lang === 'zh' ? '点击我' : 'Click me'}
                                            {/* Tooltip arrow */}
                                            <div
                                                style={{
                                                    position: 'absolute',
                                                    top: '-4px',
                                                    left: '50%',
                                                    transform: 'translateX(-50%)',
                                                    width: '0',
                                                    height: '0',
                                                    borderLeft: '4px solid transparent',
                                                    borderRight: '4px solid transparent',
                                                    borderBottom: '4px solid rgba(0, 0, 0, 0.8)'
                                                }}
                                            />
                                        </div>
                                    )}
                                </div>

                                {/* Dropdown Menu */}
                                {showUserMenu && (
                                    <div
                                        className="user-dropdown-menu"
                                        style={{
                                            position: 'absolute',
                                            top: '100%',
                                            right: '0',
                                            background: 'rgba(0, 0, 0, 0.4)',
                                            backdropFilter: 'blur(25px)',
                                            WebkitBackdropFilter: 'blur(25px)',
                                            border: '1px solid rgba(255, 255, 255, 0.15)',
                                            borderRadius: '16px',
                                            padding: '12px 0',
                                            minWidth: '160px',
                                            boxShadow: '0 16px 64px rgba(0, 0, 0, 0.5), 0 8px 24px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)',
                                            zIndex: 1000,
                                            marginTop: '8px',
                                            animation: 'fadeInScale 0.2s ease-out'
                                        }}
                                    >
                                        {/* User Info */}
                                        <div style={{
                                            padding: '12px 20px',
                                            borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
                                            marginBottom: '8px'
                                        }}>
                                            <div style={{
                                                color: 'white',
                                                fontSize: '15px',
                                                fontWeight: '600',
                                                marginBottom: '4px'
                                            }}>
                                                {user?.name}
                                            </div>
                                            <div style={{
                                                color: 'rgba(255, 255, 255, 0.8)',
                                                fontSize: '13px',
                                                marginBottom: '4px'
                                            }}>
                                                {user?.email}
                                            </div>
                                            {/* Access Level Badge */}
                                            {getAccessLevelDisplay && (
                                                <div style={{
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '6px',
                                                    fontSize: '12px',
                                                    color: 'rgba(255, 255, 255, 0.9)',
                                                    backgroundColor: 'rgba(255, 255, 255, 0.15)',
                                                    padding: '4px 8px',
                                                    borderRadius: '6px',
                                                    marginTop: '6px'
                                                }}>
                                                    <span>{getAccessLevelDisplay(lang)?.icon}</span>
                                                    <span>{getAccessLevelDisplay(lang)?.label}</span>
                                                </div>
                                            )}
                                        </div>

                                        {/* Logout Button */}
                                        <div
                                            style={{
                                                padding: '10px 20px',
                                                color: 'white',
                                                fontSize: '14px',
                                                cursor: 'pointer',
                                                transition: 'background-color 0.2s ease',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '10px',
                                                fontWeight: '500'
                                            }}
                                            onClick={handleLogout}
                                            onMouseEnter={(e) => e.target.style.backgroundColor = 'rgba(255, 255, 255, 0.1)'}
                                            onMouseLeave={(e) => e.target.style.backgroundColor = 'transparent'}
                                        >
                                            <FontAwesomeIcon icon="sign-out-alt" />
                                            {{ en: "Logout", zh: "登出" }[lang]}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <h6 
                                style={{ 
                                    color: "white", 
                                    cursor: 'pointer',
                                    margin: 0,
                                    height: '25px', // Fixed height to maintain consistency
                                    minHeight: '25px', // Ensure minimum height 
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center', // Center the content
                                    padding: '0 4px'
                                }} 
                                onClick={handleLoginClick}
                            >
                                <FontAwesomeIcon icon="user" style={{ marginRight: '4px' }} />
                                <span className="login-text">{{ en: "Login", zh: "登录" }[lang]}</span>
                                <span className="login-icon-only" style={{ display: 'none' }}></span>
                            </h6>
                        )}
                    </li>
                </ul>
            </div>

            {/* Login Modal */}
            <LoginModal 
                isOpen={showLoginModal} 
                onClose={closeLoginModal} 
                lang={lang}
            />
        </>
    );
}

export default Navigation;